    SELECT 'matorrales-mediterraneos-y-4090', '4090', 'Matorrales mediterráneos y oromediterráneos primarios y secundarios con dominio frecuente de genisteas', 'Matorral', 'Matorral almohadillado de montaña: matas espinosas y compactas —piornos, erizones, aulagas y aliagas— que crecen pegadas al suelo formando cojines redondeados. Esa forma no es casual, es la respuesta al viento, al frío y al peso de la nieve, y por dentro guarda un microclima donde se refugian otras plantas. Aparece por encima o en el lugar del bosque, en crestas y laderas expuestas.', 0, 37.872213, -1.563033, '#4f7942', '{"type":"MultiPolygon","coordinates":[[[[-1.66611,37.85855],[-1.66592,37.858],[-1.6658,37.85745],[-1.66572,37.85724],[-1.66564,37.85688],[-1.66555,37.85662],[-1.6654,37.85608],[-1.66424,37.85609],[-1.66408,37.85607],[-1.66366,37.85595],[-1.66356,37.85591],[-1.66343,37.85582],[-1.66334,37.8557],[-1.6633,37.85562],[-1.66326,37.85536],[-1.66322,37.85527],[-1.66253,37.85463],[-1.6622,37.85442],[-1.66202,37.85436],[-1.66139,37.8542],[-1.66117,37.85409],[-1.66105,37.854],[-1.66095,37.8538],[-1.66091,37.85361],[-1.66086,37.85155],[-1.66082,37.85142],[-1.66073,37.85131],[-1.66028,37.85091],[-1.65995,37.85074],[-1.65887,37.85025],[-1.65807,37.85005],[-1.65798,37.85004],[-1.6578,37.85006],[-1.65735,37.85016],[-1.65714,37.85016],[-1.65695,37.85008],[-1.65685,37.85002],[-1.65678,37.84993],[-1.65675,37.8498],[-1.6568,37.8495],[-1.65686,37.84938],[-1.65701,37.84919],[-1.65704,37.84911],[-1.65703,37.84906],[-1.65701,37.849],[-1.65695,37.84893],[-1.65672,37.84878],[-1.65662,37.84869],[-1.65656,37.84855],[-1.65655,37.84838],[-1.65656,37.84831],[-1.65661,37.84822],[-1.65683,37.84801],[-1.65686,37.84793],[-1.65684,37.84786],[-1.65678,37.84777],[-1.65669,37.84769],[-1.65664,37.84766],[-1.65641,37.8476],[-1.65627,37.84754],[-1.65613,37.84747],[-1.65586,37.84728],[-1.65576,37.84716],[-1.65563,37.84679],[-1.65557,37.8467],[-1.65547,37.84661],[-1.65517,37.84645],[-1.65501,37.84635],[-1.65478,37.84609],[