    SELECT 'encinares-de-quercus-9340', '9340', 'Encinares de Quercus ilex y Quercus rotundifolia', 'Bosque', 'El bosque mediterráneo por excelencia: encinares y carrascales de hoja dura, pequeña y perenne, que aguantan tanto el calor del verano como las heladas del interior. Bajo los árboles crece un sotobosque denso de coscoja, lentisco, madroño, enebros y aromáticas, y en el suelo la bellota sostiene en otoño a jabalíes, palomas y arrendajos. Aclarado por el ser humano durante siglos, ha dado lugar a las dehesas.', 0, 37.868219, -1.54985, '#6b8e23', '{"type":"MultiPolygon","coordinates":[[[[-1.642428,37.829813],[-1.642344,37.829641],[-1.642158,37.829515],[-1.641929,37.829445],[-1.641698,37.82942],[-1.641438,37.829419],[-1.641133,37.829452],[-1.64083,37.829459],[-1.640541,37.829458],[-1.640251,37.82948],[-1.639977,37.829477],[-1.639731,37.829487],[-1.6395,37.829485],[-1.639197,37.829447],[-1.638953,37.829357],[-1.638752,37.829262],[-1.638537,37.829158],[-1.638235,37.829067],[-1.637961,37.829041],[-1.637728,37.829119],[-1.637524,37.829232],[-1.637305,37.829344],[-1.637101,37.829457],[-1.636766,37.82959],[-1.636518,37.829691],[-1.636271,37.829769],[-1.636025,37.829823],[-1.635957,37.829833],[-1.63588,37.82991],[-1.63584,37.82993],[-1.63576,37.82989],[-1.635724,37.829862],[-1.635518,37.829878],[-1.635272,37.829875],[-1.635041,37.829884],[-1.63471,37.829848],[-1.634479,37.8298],[-1.634385,37.829776],[-1.63435,37.82995],[-1.63425,37.83014],[-1.63417,37.8304],[-1.63412,37.8305],[-1.63408,37.83051],[-1.63403,37.83051],[-1.6337,37.83043],[-1.63367,37.83041],[-1.63365,37.83031],[-1.63357,37.83014],[-1.63313,37.82947],[-1.6331,37.82943],[-1.63313,37.82939],[-1.633375,37.829314],[-1.633465,37.829077],[-1.633612,37.82893],[-1.633876,37.828762],[-1.634109,37.828661],[-1.634356,37.82856],[-1.634589,37.828425],[-1.63468,37.82821],[-1.634627,37.827993],[-1.634413,37.827785],[-1.634183,37.827681],[-1.633867,37.827646],[-1.633593,37.827609],[-1.633289,37.827585],[-1.633015,37.82758