    SELECT 'galerias-y-matorrales-92D0', '92D0', 'Galerías y matorrales ribereños termomediterráneos (Nerio-Tamaricetea)', 'Ribera', 'La vegetación leñosa de ramblas, arroyos y ríos de caudal irregular, que unos meses llevan agua y otros son un lecho de piedras: adelfares y tarayales. La adelfa (Nerium oleander), de hojas coriáceas y flores rosas, y los tarays (Tamarix), de ramillas finas y flores en espiga, resisten tanto las avenidas violentas como meses de sequía. Toda la adelfa es muy tóxica, incluidas hojas y ramas secas.', 0, 37.83215, -1.490368, '#2e8b57', '{"type":"MultiPolygon","coordinates":[[[[-1.589306,37.92102],[-1.58889,37.920939],[-1.588838,37.920996],[-1.58911,37.92107],[-1.58926,37.92105],[-1.589306,37.92102]]],[[[-1.58881,37.922196],[-1.588727,37.92219],[-1.588449,37.922038],[-1.588088,37.921881],[-1.587463,37.921864],[-1.587447,37.921872],[-1.58786,37.92207],[-1.58809,37.92221],[-1.58834,37.92233],[-1.58855,37.92234],[-1.58875,37.92228],[-1.58881,37.922196]]],[[[-1.58735,37.92276],[-1.58726,37.92268],[-1.58707,37.92264],[-1.58692,37.92263],[-1.586918,37.92263],[-1.587072,37.922761],[-1.587339,37.92279],[-1.58735,37.92276]]],[[[-1.586367,37.923963],[-1.586137,37.923889],[-1.585714,37.923866],[-1.585648,37.923931],[-1.58579,37.92401],[-1.58602,37.92407],[-1.58625,37.92405],[-1.586367,37.923963]]],[[[-1.57741,37.9331],[-1.57698,37.93289],[-1.5764,37.93255],[-1.576149,37.932266],[-1.576058,37.932357],[-1.575927,37.932436],[-1.575825,37.932507],[-1.575753,37.93261],[-1.575665,37.932712],[-1.575593,37.932802],[-1.575564,37.932905],[-1.575563,37.933031],[-1.575519,37.933125],[-1.575478,37.933215],[-1.57555,37.93334],[-1.57658,37.93377],[-1.57681,37.93348],[-1.57741,37.9331]]],[[[-1.534736,37.921621],[-1.534705,37.921435],[-1.534365,37.92062],[-1.533953,37.919876],[-1.533709,37.919003],[-1.533698,37.917984],[-1.533876,37.917212],[-1.534305,37.916604],[-1.534313,37.916582],[-1.534308,37.916555],[-1.534294,37.916541],[-1.534263,37.916522],[-1.534233,37.9165