    SELECT 'prados-humedos-mediterraneos-6420', '6420', 'Prados húmedos mediterráneos de hierbas altas del Molinion-Holoschoenion', 'Pastos', 'Juncales altos sobre suelos que mantienen humedad en profundidad todo el verano, aunque la superficie esté seca: bordes de acequia, manantiales, vegas y fondos de valle. El junco churrero (Scirpoides holoschoenus) forma macollas robustas entre las que crecen menta, lirios y a menudo orquídeas. Es un oasis de verde en pleno agosto, y desaparece en cuanto se drena o se capta el agua que lo alimenta.', 0, 37.859793, -1.531608, '#8b5e34', '{"type":"MultiPolygon","coordinates":[[[[-1.589306,37.92102],[-1.58889,37.920939],[-1.588838,37.920996],[-1.58911,37.92107],[-1.58926,37.92105],[-1.589306,37.92102]]],[[[-1.58881,37.922196],[-1.588727,37.92219],[-1.588449,37.922038],[-1.588088,37.921881],[-1.587463,37.921864],[-1.587447,37.921872],[-1.58786,37.92207],[-1.58809,37.92221],[-1.58834,37.92233],[-1.58855,37.92234],[-1.58875,37.92228],[-1.58881,37.922196]]],[[[-1.58735,37.92276],[-1.58726,37.92268],[-1.58707,37.92264],[-1.58692,37.92263],[-1.586918,37.92263],[-1.587072,37.922761],[-1.587339,37.92279],[-1.58735,37.92276]]],[[[-1.586367,37.923963],[-1.586137,37.923889],[-1.585714,37.923866],[-1.585648,37.923931],[-1.58579,37.92401],[-1.58602,37.92407],[-1.58625,37.92405],[-1.586367,37.923963]]],[[[-1.57741,37.9331],[-1.57698,37.93289],[-1.5764,37.93255],[-1.576149,37.932266],[-1.576058,37.932357],[-1.575927,37.932436],[-1.575825,37.932507],[-1.575753,37.93261],[-1.575665,37.932712],[-1.575593,37.932802],[-1.575564,37.932905],[-1.575563,37.933031],[-1.575519,37.933125],[-1.575478,37.933215],[-1.57555,37.93334],[-1.57658,37.93377],[-1.57681,37.93348],[-1.57741,37.9331]]],[[[-1.564106,37.886294],[-1.564102,37.886275],[-1.564088,37.886262],[-1.564059,37.886252],[-1.564033,37.886261],[-1.564016,37.886279],[-1.564016,37.886297],[-1.564031,37.886315],[-1.564072,37.886325],[-1.564097,37.886311],[-1.564106,37.886294]]],[[[-1.561779,37.874432],[