    SELECT 'pendientes-rocosas-calcicolas-8210', '8210', 'Pendientes rocosas calcícolas con vegetación casmofítica', 'Roquedos', 'Paredes y cortados de roca caliza en los que la vegetación no vive sobre el suelo, sino dentro de las fisuras. Son plantas de raíz larguísima y crecimiento lentísimo, agarradas a la grieta, que aprovechan el agua que escurre por la pared. Los roquedos han quedado a salvo del arado y del ganado durante milenios, y por eso concentran una proporción altísima de especies que no existen en ningún otro lugar.', 0, 37.868631, -1.559844, '#daa520', '{"type":"MultiPolygon","coordinates":[[[[-1.659517,37.854007],[-1.659491,37.853295],[-1.658117,37.852376],[-1.657455,37.852335],[-1.656942,37.852502],[-1.656455,37.852731],[-1.655886,37.852853],[-1.655073,37.852945],[-1.654588,37.853149],[-1.653868,37.853724],[-1.652852,37.85451],[-1.652412,37.855289],[-1.652178,37.855983],[-1.652123,37.856268],[-1.652748,37.856481],[-1.653827,37.856567],[-1.65498,37.856646],[-1.656122,37.856607],[-1.656884,37.856686],[-1.657084,37.85706],[-1.656719,37.857783],[-1.654813,37.858751],[-1.652888,37.859785],[-1.651457,37.860778],[-1.649143,37.862146],[-1.647687,37.863035],[-1.646094,37.864092],[-1.644553,37.864966],[-1.643721,37.865471],[-1.643067,37.865878],[-1.642455,37.866319],[-1.642281,37.866668],[-1.642223,37.866988],[-1.642241,37.86724],[-1.642384,37.867898],[-1.642578,37.867767],[-1.643,37.867709],[-1.643503,37.867746],[-1.644691,37.867676],[-1.646207,37.867029],[-1.647298,37.866246],[-1.648384,37.86584],[-1.649832,37.865135],[-1.651104,37.864149],[-1.65282,37.862914],[-1.65418,37.862218],[-1.655167,37.861787],[-1.65586,37.861462],[-1.656222,37.860977],[-1.656916,37.860149],[-1.657652,37.859515],[-1.658186,37.859199],[-1.658593,37.858809],[-1.6589,37.858094],[-1.658926,37.857177],[-1.658824,37.856246],[-1.658406,37.855926],[-1.657835,37.856081],[-1.657298,37.856147],[-1.657069,37.856084],[-1.657156,37.855765],[-1.657975,37.855202],[-1.658926,37.854622],[-1.659517,