    SELECT 'prados-alpinos-y-6170', '6170', 'Prados alpinos y subalpinos calcáreos', 'Pastos', 'Pastos de alta montaña sobre suelos calizos, por encima del límite del bosque, donde la nieve cubre el terreno buena parte del año. Son céspedes bajos, densos y muy diversos, con plantas de porte enano y flores desproporcionadamente grandes que florecen en cuanto se funde la nieve. El corto verano y el pastoreo tradicional han modelado juntos este paisaje.', 0, 37.870192, -1.579297, '#a0522d', '{"type":"Polygon","coordinates":[[[-1.627438,37.860523],[-1.627257,37.860037],[-1.626435,37.859694],[-1.624201,37.859607],[-1.622273,37.859463],[-1.62114,37.859591],[-1.620581,37.859828],[-1.620214,37.859943],[-1.6196,37.859467],[-1.619429,37.859096],[-1.619368,37.858843],[-1.619286,37.85845],[-1.61926,37.857749],[-1.619006,37.857284],[-1.618552,37.857112],[-1.617846,37.857079],[-1.616709,37.857322],[-1.615492,37.858033],[-1.614327,37.858563],[-1.61302,37.858721],[-1.612142,37.858652],[-1.611798,37.858596],[-1.610883,37.858076],[-1.610117,37.857781],[-1.609359,37.857598],[-1.608632,37.857394],[-1.607891,37.85718],[-1.607313,37.857187],[-1.606836,37.857528],[-1.606419,37.858422],[-1.605848,37.859553],[-1.605411,37.860262],[-1.605044,37.860711],[-1.604699,37.860988],[-1.604914,37.861349],[-1.604551,37.861694],[-1.60323,37.862174],[-1.60119,37.862253],[-1.599926,37.862092],[-1.598888,37.862062],[-1.597757,37.862156],[-1.596592,37.862377],[-1.595385,37.862549],[-1.594445,37.862259],[-1.593604,37.861708],[-1.592708,37.861395],[-1.591622,37.861159],[-1.591073,37.860844],[-1.590683,37.860513],[-1.590381,37.860182],[-1.589957,37.860619],[-1.589684,37.861206],[-1.589615,37.861755],[-1.589763,37.862322],[-1.590036,37.862972],[-1.590353,37.863622],[-1.590261,37.864054],[-1.58977,37.864386],[-1.589454,37.864639],[-1.589273,37.865128],[-1.588866,37.865518],[-1.586949,37.865727],[-1.584452,37.865692],[-1.582716,37.865435],[-1.581463,37.865046],[-1.58053,37.864926],[-1.579829,37.86478],[-1.578634