    SELECT 'robledales-ibericos-de-9240', '9240', 'Robledales ibéricos de Quercus faginea y Quercus canariensis', 'Bosque', 'Bosques de quejigo (Quercus faginea) y quejigo andaluz (Quercus canariensis), parientes de la encina que buscan más humedad y suelos más profundos: umbrías, vaguadas y pies de sierra. Su hoja es marcescente, es decir, se seca en otoño pero no cae hasta que empuja la nueva, así que en invierno el bosque se queda de color pardo dorado en vez de desnudo. Bajo su sombra prospera un sotobosque más rico y verde que el del encinar.', 0, 37.878961, -1.550537, '#556b2f', '{"type":"Polygon","coordinates":[[[-1.561876,37.881044],[-1.561854,37.880275],[-1.561261,37.879639],[-1.559907,37.879246],[-1.558923,37.878989],[-1.55704,37.878466],[-1.556343,37.87793],[-1.555771,37.877488],[-1.55538,37.87719],[-1.555092,37.876873],[-1.554199,37.876493],[-1.553075,37.876128],[-1.552393,37.876189],[-1.552039,37.876671],[-1.551695,37.877224],[-1.551133,37.877505],[-1.550498,37.8775],[-1.549733,37.877168],[-1.549163,37.876692],[-1.548541,37.876399],[-1.547933,37.876416],[-1.547262,37.87657],[-1.546352,37.876876],[-1.545671,37.877224],[-1.544486,37.877236],[-1.542779,37.876992],[-1.541097,37.876496],[-1.540266,37.876037],[-1.539776,37.875391],[-1.539539,37.874915],[-1.539717,37.874496],[-1.539943,37.873999],[-1.539147,37.874331],[-1.538495,37.87469],[-1.53807,37.875124],[-1.538123,37.875551],[-1.538523,37.876261],[-1.539004,37.877089],[-1.539397,37.877962],[-1.539912,37.878984],[-1.540296,37.879442],[-1.540657,37.879762],[-1.541141,37.879903],[-1.541678,37.879838],[-1.542078,37.879631],[-1.542347,37.879434],[-1.542698,37.879361],[-1.542953,37.87945],[-1.543345,37.879725],[-1.543576,37.88003],[-1.543947,37.880465],[-1.544258,37.880599],[-1.544673,37.880679],[-1.545225,37.880616],[-1.545919,37.880291],[-1.546724,37.879754],[-1.547399,37.879532],[-1.548174,37.879623],[-1.548607,37.879955],[-1.549199,37.880591],[-1.549719,37.880892],[-1.550207,37.880964],[-1.550658,37.880897