    SELECT 'bosques-galeria-de-92A0', '92A0', 'Bosques galería de Salix alba y Populus alba', 'Ribera', 'Alamedas y saucedas: la banda de árboles de hoja caduca que acompaña a los ríos, con el álamo blanco de envés plateado, chopos y sauces de raíces dentro del agua. Dan sombra al cauce, sujetan las orillas en las crecidas y sostienen una fauna que no aparece a veinte metros de allí. Es un bosque estrecho y alargado que funciona además como corredor entre sierras.', 0, 37.859793, -1.531608, '#6b8e23', '{"type":"Polygon","coordinates":[[[-1.543272,37.858099],[-1.543254,37.858081],[-1.54323,37.858069],[-1.542854,37.857975],[-1.542371,37.85807],[-1.541688,37.858449],[-1.541385,37.858693],[-1.540563,37.858782],[-1.539142,37.859073],[-1.538036,37.858951],[-1.536814,37.858801],[-1.535542,37.858695],[-1.535011,37.858709],[-1.53446,37.858722],[-1.533205,37.858954],[-1.53222,37.859435],[-1.531474,37.8598],[-1.530739,37.859967],[-1.529916,37.859864],[-1.529159,37.859866],[-1.528587,37.860062],[-1.528163,37.860245],[-1.52788,37.860866],[-1.527745,37.861295],[-1.527512,37.861643],[-1.527002,37.861822],[-1.526391,37.861839],[-1.525893,37.861715],[-1.52564,37.861455],[-1.525477,37.860978],[-1.525252,37.860432],[-1.524851,37.860064],[-1.524305,37.860024],[-1.523667,37.860214],[-1.523112,37.860288],[-1.522655,37.860273],[-1.52212,37.860294],[-1.521671,37.860446],[-1.520915,37.860648],[-1.520915,37.860649],[-1.520894,37.860654],[-1.520866,37.860665],[-1.520847,37.860681],[-1.520846,37.860698],[-1.520848,37.860726],[-1.520869,37.860755],[-1.520899,37.860766],[-1.520937,37.860759],[-1.520948,37.860754],[-1.521719,37.860546],[-1.522151,37.860402],[-1.522656,37.860382],[-1.523121,37.860396],[-1.523702,37.860318],[-1.524323,37.860132],[-1.524784,37.860167],[-1.525131,37.860485],[-1.525347,37.861008],[-1.525515,37.861503],[-1.525812,37.861809],[-1.526372,37.861947],[-1.527033,37.86193],[-1.52761,37.861726],[-1.527873,37.861332],[-1.52801,37.860899],[-1.528273,37.860319],[-1.528647,37.8601