-- ------------------------------------------------------------------------------------------------
INSERT INTO species (park_id, common_name, scientific_name, kingdom, family, primary_habitat, conservation_status, description, description_source, identification_tips, seasonality, image_url, image_attribution, latitude, longitude, rarity_score, rarity_basis, rarity_local, rarity_local_basis, is_featured, is_visible, hidden_reason, source, taxon_phylum, taxon_class, taxon_order, taxon_family, taxon_genus, iucn_global, spain_status, murcia_status, review_note, eidos_taxonid, gbif_species_key, zepa_site_code, is_migratory, site_presence)
SELECT pk.id, s.common_name, s.scientific_name, s.kingdom, s.family, s.primary_habitat, s.conservation_status, s.description, s.description_source, s.identification_tips, s.seasonality, s.image_url, s.image_attribution, s.latitude, s.longitude, s.rarity_score, s.rarity_basis, s.rarity_local, s.rarity_local_basis, s.is_featured, s.is_visible, s.hidden_reason, s.source, s.taxon_phylum, s.taxon_class, s.taxon_order, s.taxon_family, s.taxon_genus, s.iucn_global, s.spain_status, s.murcia_status, s.review_note, s.eidos_taxonid, s.gbif_species_key, s.zepa_site_code, s.is_migratory, s.site_presence
FROM parks pk JOIN (
    SELECT 'Pino carrasco' common_name, 'Pinus halepensis' scientific_name, 'flora' kingdom, 'Conífera' family, 'Laderas secas y soleadas sobre calizas y margas, en clima mediterráneo cálido' primary_habitat, 'Aprovechamiento regulado' conservation_status, 'Pino de copa clara e irregular y follaje de un verde pálido, el más resistente a la sequía y a los suelos pobres de los pinos ibéricos. Sus piñas, alargadas y asimétricas, quedan colgadas años en la rama y liberan las semillas tras los incendios, lo que le permite recolonizar rápido.' description, NULL description_source, 'Copa irregular y poco densa, de verde claro; Piñas asimétricas y persistentes, apuntando hacia atrás; Corteza clara y agrietada, rojiza en las ramas jóvenes' identification_tips, 'Todo el año' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pino_secolare_-_Castelleone_di_Suasa.JPG?width=1280' image_url, 'Accurimbono (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}' rarity_basis, 1 rarity_local, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}' rarity_local_basis, 0 is_featured, 1 is_visible, NULL hidden_reason, 'EIDOS (IEPNB, MITECO) para taxonomía y estado de protección' source, 'Tracheophyta' taxon_phylum, 'Pinopsida' taxon_class, 'Pinales' taxon_order, 'Pinaceae' taxon_family, 'Pinus' taxon_genus, 'LC' iucn_global, 'No catalogada (especie forestal común)' spain_status, 'Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): aprovechamiento sujeto a autorización previa' murcia_status, 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.' review_note, 7118 eidos_taxonid, 5285604 gbif_species_key, NULL zepa_site_code, NULL is_migratory, NULL site_presence
    UNION ALL
    SELECT 'Jabalí', 'Sus scrofa', 'fauna', 'Mamífero ungulado', 'Bosque, matorral denso y cultivos; necesita cobertura y puntos de agua', 'Preocupación menor', 'Ungulado robusto y adaptable, con el cuerpo cubierto de cerdas ásperas y una cabeza en cuña rematada por un hocico potente con el que remueve el suelo. Los rayones —las crías— nacen con líneas claras a lo largo del lomo. Es omnívoro y ha ampliado mucho su área en las últimas décadas.', NULL, 'Hozaduras: zonas de suelo removido como si lo hubieran arado; Huellas hendidas grandes con las pezuñas laterales marcadas; Barros y árboles con el tronco embarrado a media altura', 'Todo el año (actividad sobre todo nocturna)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Eberswalde_Zoo_12-2017_img2.jpg?width=1280', 'A.Savin (FAL) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Wikipedia', 'Chordata', 'Mammalia', 'Artiodactyla', 'Suidae', 'Sus', 'LC', 'No catalogada (especie cinegética común)', 'No catalogada regionalmente', 'Foto localizada por búsqueda en Commons (no por el elemento de Wikidata del taxón): conviene confirmar que corresponde a esta especie. La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 12178, 7705930, NULL, NULL, NULL
    UNION ALL
    SELECT 'Romero', 'Rosmarinus officinalis', 'flora', 'Mata aromática', 'Matorral seco y soleado sobre suelos calizos y pedregosos', 'No amenazada', 'Arbusto aromático de hojas estrechas como agujas, verde oscuro por el haz y blanquecinas por el envés, con los bordes enrollados hacia abajo. Florece casi todo el año en azul pálido, y en pleno invierno es una de las pocas fuentes de néctar del matorral.', NULL, 'Hojas como agujas, blancas por debajo; Olor inconfundible al frotar entre los dedos; Flores azul claro repartidas por las ramas casi todo el año', 'Todo el año, con máximo de floración en invierno y primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rosemary_in_bloom.JPG?width=1280', 'Margalob (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie característica del matorral termomediterráneo (hábitat 5330; romerales del Rosmarino-Ericion) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; muy común en la Región de Murcia. Sinónimo: Rosmarinus officinalis. Ficha básica (mínima), pendiente de ampliar. Nombre aceptado en EIDOS; Salvia rosmarinus es sinónimo.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Rosmarinus', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); muy común en la Región', 'Ficha básica: especie característica del matorral semiárido, muy común en la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.', 7647, 10902460, NULL, NULL, NULL
    UNION ALL
    SELECT 'Zorro', 'Vulpes vulpes', 'fauna', 'Mamífero carnívoro', 'Prácticamente cualquier ambiente: bosque, matorral, cultivos y periferias urbanas', 'Preocupación menor', 'El carnívoro silvestre más adaptable y extendido: vive desde la alta montaña hasta el borde de las ciudades. Es omnívoro y oportunista, lo que explica su éxito. Se reconoce por la cola larga y espesa —la «hopa»— rematada casi siempre en blanco.', NULL, 'Cola muy espesa con la punta blanca; Huella alargada con las cuatro almohadillas alineadas; Excrementos retorcidos y con pelos, sobre piedras y caminos', 'Todo el año (actividad sobre todo nocturna)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Vulpes_vulpes_2.jpg?width=1280', 'Juan Lacruz (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Wikipedia', 'Chordata', 'Mammalia', 'Carnivora', 'Canidae', 'Vulpes', 'LC', 'No catalogada (especie cinegética común)', 'No catalogada regionalmente', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 12419, 5219243, NULL, NULL, NULL
    UNION ALL
    SELECT 'Coscoja', 'Quercus coccifera', 'flora', 'Arbusto', 'Matorral esclerófilo y sabinar', 'Interés especial', 'Arbusto esclerófilo de hoja perenne y espinosa, integrante del matorral mediterráneo denso y de las orlas del sabinar.', NULL, 'Hojas coriáceas con margen espinoso; Bellota con cúpula de escamas punzantes; Porte arbustivo denso', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Quercus_coccifera_1.JPG?width=1280', 'User:Xemenendura (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, NULL, 3, '{"categoria":"Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial (Anexo II: aprovechamiento sujeto a autorización)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Tracheophyta', 'Magnoliopsida', 'Fagales', 'Fagaceae', 'Quercus', 'LC (Preocupación menor)', 'No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)', 'Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial (Anexo II: aprovechamiento sujeto a autorización)', 'Especie añadida desde el Catálogo de Flora Silvestre Protegida del Anexo I del PORN; la asignación de hábitat es una inferencia ecológica (el Anexo no la vincula a una asociación concreta) y las coordenadas son representativas, no de una localización verificada. Confirmar en campo. La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 7478, 2879175, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lentisco', 'Pistacia lentiscus', 'flora', 'Arbusto', 'Matorral mediterráneo litoral', 'Aprovechamiento regulado', 'Arbusto perennifolio de hojas compuestas sin foliolo terminal y con el raquis alado, un detalle que lo separa de la cornicabra. Al frotarlo huele intensamente a resina. Sus frutos, en racimo, pasan de rojo a negro y son alimento clave para aves en otoño.', NULL, 'Hoja compuesta con número par de foliolos, sin uno terminal; Raquis de la hoja con dos alas laterales; Olor fuerte a resina al frotar las hojas', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pistacia_lentiscus.jpg?width=1280', 'Lumbar~commonswiki (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado de protección', 'Tracheophyta', 'Magnoliopsida', 'Sapindales', 'Anacardiaceae', 'Pistacia', 'LC', 'No catalogada (especie común mediterránea)', 'Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): aprovechamiento sujeto a autorización previa', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 7129, 3190583, NULL, NULL, NULL
    UNION ALL
    SELECT 'Sabina negral', 'Juniperus phoenicea', 'flora', 'Conífera', 'Roquedos, arenales, acantilados y crestas ventosas sobre suelos pobres', 'Interés botánico', 'Sabina de hojas diminutas en forma de escama, pegadas a la ramilla, que dan a las ramas un aspecto de cordón redondeado. Aguanta viento, sequía y salinidad como pocas plantas leñosas. Sus gálbulos —los falsos frutos— maduran de verde a un rojo pardusco en dos años.', NULL, 'Hojas en escama pegadas a la rama, no punzantes; Ramillas cilíndricas, como cordones; Gálbulos redondos que pasan de verde a pardo rojizo', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Juniperus_phoenicea1.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 1, 1, NULL, 'Wikipedia', 'Tracheophyta', 'Pinopsida', 'Pinales', 'Cupressaceae', 'Juniperus', 'LC', 'No catalogada en la Lista Roja de la Flora Vascular Española 2008', 'No incluida en el Catálogo Regional de Flora Silvestre Protegida; población de Cabo Cope señalada por su interés biogeográfico (aislada del resto de su área)', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 5509, 2684640, NULL, NULL, NULL
    UNION ALL
    SELECT 'Romerina', 'Cistus clusii', 'flora', 'Mata', 'Tomillares y matorral seco sobre calizas y margas', 'No amenazada', 'Jara pequeña de hojas muy estrechas y enrolladas por los bordes, verdes arriba y blancas por debajo, que a distancia recuerdan al romero. Se distingue enseguida al florecer: da grupos de flores blancas de cinco pétalos, mucho mayores que las del romero.', NULL, 'Hojas estrechas enrolladas, blancas por el envés; Flores blancas de cinco pétalos, varias juntas; Sin el olor a romero, aunque se le parezca de lejos', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cistus_clusii_(habitus).jpg?width=1280', 'Hans Hillewaert (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie característica de los matorrales y romerales del hábitat 5330 (matorral termomediterráneo semiárido) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia. Ficha básica (mínima), pendiente de ampliar.', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Cistus', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); frecuente en la Región', 'Ficha básica: especie característica del matorral semiárido, frecuente en la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.', 3610, 7331346, NULL, NULL, NULL
    UNION ALL
    SELECT 'Albaida', 'Anthyllis cytisoides', 'flora', 'Mata', 'Matorral seco y soleado sobre margas y suelos pobres', 'No amenazada', 'Mata de aspecto blanquecino por la fina pelusa que cubre hojas y tallos, un recurso frente al sol y la sequía. En primavera se llena de espigas de flores amarillas que atraen a muchos insectos. Es una de las leguminosas que primero coloniza laderas degradadas y taludes.', NULL, 'Aspecto grisáceo y aterciopelado al tacto; Flores amarillas pequeñas en espigas apretadas; Hojas divididas en tres, la del centro más larga', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Anthyllis_cytisoides.JPG?width=1280', 'Ximenex (CC BY-SA 2.1 es) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie característica del hábitat 5330 (matorral termomediterráneo semiárido) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; muy extendida por la Región de Murcia (ficha de flora de regmurcia.com y Región de Murcia Digital). Ficha básica (mínima), pendiente de ampliar.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Anthyllis', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); muy extendida por la Región', 'Ficha básica: especie característica del matorral semiárido, muy extendida por la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.', 2186, 5352466, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lastón', 'Brachypodium retusum', 'flora', 'Gramínea', 'Pastizales, claros de matorral y ribazos sobre suelos calizos', 'No amenazada', 'Gramínea perenne y rizomatosa que forma céspedes extensos en los claros del matorral mediterráneo. Sus hojas son cortas, rígidas y de punta roma. Es de las plantas que más rápido rebrota tras un incendio, gracias a sus rizomas subterráneos.', NULL, 'Céspedes extensos y bajos, no matas aisladas; Hojas cortas y rígidas, de punta redondeada; Espiguillas alineadas a un lado de un eje rígido', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Brachypodium_retusum_espiga_seca.jpg?width=1280', 'Pere prlpz (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie estructural del hábitat prioritario de interés comunitario 6220* (Zonas subestépicas de gramíneas y anuales del Thero-Brachypodietea; asociación Teucrio pseudochamaepityos-Brachypodietum ramosi) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia, franja costera e interior (Región de Murcia Digital). Sinónimo: Brachypodium ramosum. Ficha básica (mínima), pendiente de ampliar.; IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Brachypodium', 'LC (Preocupación menor)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); muy frecuente en la Región', 'Ficha básica: especie estructural del hábitat prioritario 6220*, frecuente en la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado; pendiente de confirmación en campo y de ampliar la ficha.', 9931, 5676053, NULL, NULL, NULL
    UNION ALL
    SELECT 'Mata pulguera', 'Phagnalon saxatile', 'flora', 'Mata', 'Roquedos, muros, taludes y grietas soleadas', 'No amenazada', 'Mata pequeña y leñosa en la base que crece agarrada a la roca y a los muros. Sus hojas son estrechas y blanquecinas por el envés. Las cabezuelas, solitarias sobre tallos largos y desnudos, están rodeadas de brácteas secas y pardas que persisten mucho tiempo.', NULL, 'Cabezuelas pardas y secas al final de tallos largos y pelados; Hojas estrechas, verdes arriba y blancas por debajo; Casi siempre sobre roca, muro o talud', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Phagnalon_saxatile.JPG?width=1280', 'Xemenendura (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie característica de los claros pedregosos y roquedos (hábitats 5330 y 8210) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia. Sinónimo: Phagnalon rupestre s.l. Ficha básica (mínima), pendiente de ampliar.', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Phagnalon', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); frecuente en la Región', 'Ficha básica: especie característica de matorral y roquedos, frecuente en la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.', 9655, 3150065, NULL, NULL, NULL
    UNION ALL
    SELECT 'Esparraguera de gato', 'Asparagus horridus', 'flora', 'Arbusto', 'Matorrales arborescentes de Juniperus spp.', 'No amenazada', 'Esparraguera muy espinosa y densa que se enreda entre el matorral y el sabinar litoral, con cladodios rígidos y punzantes.', NULL, 'Cladodios rígidos y punzantes; Se enreda en el matorral; Frutos negros en otoño', 'Otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Asparagus_stipularis_(detail).jpg?width=1280', 'Hans Hillewaert (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO) — especie característica del HIC 5210; Inventario Español EIDOS (IEPNB, taxonid 33035); GBIF (speciesKey 2768695); Matorrales arborescentes de Juniperus (HIC 5210).', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Asparagaceae', 'Asparagus', 'LC', 'No incluida en el LESRPE; acompañante de sabinares y matorrales termófilos (HIC 5210)', 'No catalogada; frecuente en el matorral termomediterráneo del sureste', NULL, 33035, 2768695, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cardo amarillo de roca', 'Centaurea saxicola', 'flora', 'Hierba', 'Roquedos y fisuras calcáreas costeras', 'Vulnerable', 'Compuesta rupícola que crece colgando de las fisuras de los cantiles calizos, con hojas divididas y algo carnosas y capítulos amarillos rodeados de brácteas con apéndices espinosos. Es un endemismo del sureste ibérico ligado a paredes de roca costeras y de interior.', NULL, 'Capítulos amarillos con brácteas de apéndice espinoso; Hojas divididas y algo carnosas, en roseta colgante; Crece encajada en la grieta, no en el suelo', 'Floración primaveral', 'https://commons.wikimedia.org/wiki/Special:FilePath/Centaurea_saxicola674.jpg?width=1280', 'Nanosanchez (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 4, NULL, 4, '{"categoria":"Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado de protección', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Centaurea', 'NE', 'Pendiente de contrastar con la Lista Roja de la Flora Vascular Española 2008', 'Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable', 'Especie añadida a partir del PORN; falta contrastar su distribución exacta dentro del parque y su presencia en la Lista Roja de la Flora Vascular Española 2008. La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 3332, 3128450, NULL, NULL, NULL
    UNION ALL
    SELECT 'Oroval', 'Withania frutescens', 'flora', 'Arbusto', 'Matorral cálido, roquedos y ramblas de clima muy seco', 'Interés biogeográfico', 'Arbusto de la familia del tomate y la belladona, con hojas ovaladas algo carnosas y flores verdosas discretas. Los frutos son bayas rojas y brillantes envueltas en el cáliz. Es una especie de raíz norteafricana que en la península solo vive en los rincones más cálidos del sureste.', NULL, 'Bayas rojas pequeñas asomando del cáliz; Hojas ovales, algo carnosas y de verde apagado; Flores verde amarillentas, poco vistosas', 'Primavera y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Withania_frutescens0176.jpg?width=1280', 'Nanosanchez (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie característica de los matorrales térmicos del sureste (hábitats 5330 y azufaifar 5220), iberoafricanismo, según las fichas de flora de la Región de Murcia (regmurcia.com, ficha Withania frutescens - Oroval) y las Bases ecológicas de la Red Natura 2000. Sinónimo: Withania frutescens (L.) Pauquy. Ficha básica (mínima), pendiente de ampliar.', 'Tracheophyta', 'Magnoliopsida', 'Solanales', 'Solanaceae', 'Withania', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE; elemento iberoafricano de interés biogeográfico', 'No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); elemento iberoafricano característico del sureste árido', 'Ficha básica: iberoafricanismo característico de los matorrales térmicos del sureste, documentado en la Región de Murcia. Presencia en el parque inferida del hábitat y del carácter iberoafricano de su flora; pendiente de confirmación en campo y de ampliar la ficha.', 9438, 3801152, NULL, NULL, NULL
    UNION ALL
    SELECT 'Jarilla de Almería', 'Helianthemum almeriense', 'flora', 'Mata', 'Tomillares y matorral abierto sobre suelos secos y pedregosos', 'No amenazada', 'Jarilla enana de hojas pequeñas y blanquecinas, cubiertas de pelos que reflejan la luz y reducen la pérdida de agua. En primavera se cubre de flores blancas con el centro amarillo, cuyos pétalos duran apenas una mañana. Sus raíces se asocian con hongos comestibles del desierto.', NULL, 'Mata baja y grisácea, de hojas muy pequeñas; Flores blancas con el centro amarillo, efímeras; Pétalos arrugados, como de papel de seda', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Helianthemum_almeriense_flor.jpg?width=1280', 'Retama (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie característica de los tomillares y matorrales áridos del sureste (hábitat 5330) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; propia del sureste ibérico y la Región de Murcia. Ficha básica (mínima), pendiente de ampliar.', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Helianthemum', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); propia del sureste árido y la Región', 'Ficha básica: especie característica de los tomillares del sureste, propia de la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.', 4958, 7331316, NULL, NULL, NULL
    UNION ALL
    SELECT 'Baladre', 'Nerium oleander', 'flora', 'Arbusto', 'Cauces de rambla y ramblizos con humedad subterránea y crecidas', 'No amenazada', 'Arbusto de hojas coriáceas, alargadas y opuestas, que forma masas densas en el lecho de las ramblas y aguanta las riadas gracias a su raigambre. Florece en rosa intenso durante buena parte del verano. Toda la planta es muy tóxica, savia incluida.', NULL, 'Hojas duras y lanceoladas con el nervio central marcado; Flores rosas grandes en el extremo de las ramas; Frutos en vaina larga que se abre soltando semillas con vilano', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Nerium_oleander_flowers_leaves.jpg?width=1280', 'Alvesgaspar (CC BY 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie característica del hábitat de interés comunitario 92D0 (Galerías y matorrales ribereños termomediterráneos, Nerio-Tamaricetea) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; forma los adelfares de las ramblas de la Región de Murcia (Región de Murcia Digital). Ficha básica (mínima), pendiente de ampliar.; IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Tracheophyta', 'Magnoliopsida', 'Gentianales', 'Apocynaceae', 'Nerium', 'LC (Preocupación menor)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); característica de las ramblas de la Región', 'Ficha básica: especie característica del hábitat 92D0 documentada en las ramblas de la Región de Murcia. Presencia en el parque inferida del hábitat cartografiado; pendiente de confirmación en campo y de ampliar la ficha.', 6561, 3169756, NULL, NULL, NULL
    UNION ALL
    SELECT 'Eragrostis', 'Eragrostis papposa', 'flora', 'Gramínea', 'Pastizales de la subestepa de gramíneas', 'Interés especial', 'Gramínea de panícula muy abierta y ligera, con espiguillas diminutas sostenidas por ramas finísimas que tiemblan con el viento. Es una planta de estirpe saharo-arábiga que en Europa solo aparece en los enclaves más áridos del sureste ibérico.', NULL, 'Panícula muy abierta y difusa, casi transparente; Espiguillas diminutas colgando de ramas capilares; Mata pequeña, de menos de medio metro', 'Verano', 'https://inaturalist-open-data.s3.amazonaws.com/photos/591856810/original.jpg', 'Alejandro Rodríguez Zapata (CC BY 4.0) · GBIF/iNaturalist', NULL, NULL, 4, NULL, 3, '{"categoria":"Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado de protección', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Eragrostis', 'NE', 'No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)', 'Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial', 'Especie añadida desde el Catálogo de Flora Silvestre Protegida del Anexo I del PORN; la asignación de hábitat es una inferencia ecológica (el Anexo no la vincula a una asociación concreta) y las coordenadas son representativas, no de una localización verificada. Confirmar en campo. La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 10023, 4143386, NULL, NULL, NULL
    UNION ALL
    SELECT 'Acebuche', 'Olea europaea subsp. europaea', 'flora', 'Árbol', 'Matorral alto, laderas secas y barrancos del piso más cálido', 'Interés botánico / aprovechamiento regulado', 'El acebuche es el olivo silvestre: mismo árbol, sin siglos de selección. Tiene las hojas más pequeñas y duras, las ramas jóvenes a menudo espinosas y aceitunas diminutas. Forma matorrales altos y es el árbol característico de las laderas cálidas mediterráneas.', NULL, 'Hojas pequeñas, verdes arriba y plateadas por debajo; Ramillas jóvenes rígidas y a veces espinosas; Aceitunas muy pequeñas, de poco más de un centímetro', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ullastre_vell.JPG?width=1280', 'Antoni Salvà (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado de protección Nombre aceptado en EIDOS; Olea europaea var. sylvestris es sinónimo.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Oleaceae', 'Olea', 'LC', 'No catalogada en la Lista Roja de la Flora Vascular Española 2008', 'Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): aprovechamiento sujeto a autorización previa (poblaciones silvestres)', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 32803, 8028262, NULL, NULL, NULL
    UNION ALL
    SELECT 'Orejilla de roca', 'Lafuentea rotundifolia', 'flora', 'Hierba', 'Roquedos y fisuras calcáreas costeras', 'Vulnerable', 'Planta rupícola de hojas redondeadas, dentadas y algo carnosas, que forma matas colgantes en las paredes calizas. Sus flores, blanquecinas con toques amarillos, se agrupan en racimos erguidos. Es un endemismo iberoafricano restringido al sureste peninsular y al norte de África.', NULL, 'Hojas redondas y dentadas, casi como monedas; Racimos de flores blanquecinas erguidos sobre el follaje; Forma matas colgantes en pared caliza', 'Floración primaveral', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lafuentea_rotundifolia80857.jpg?width=1280', 'Nanosanchez (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 4, NULL, 4, '{"categoria":"Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado de protección', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Plantaginaceae', 'Lafuentea', 'NE', 'Pendiente de contrastar con la Lista Roja de la Flora Vascular Española 2008', 'Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable', 'Especie añadida a partir del PORN; falta contrastar su distribución exacta dentro del parque y su presencia en la Lista Roja de la Flora Vascular Española 2008. La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 5616, 3739515, NULL, NULL, NULL
    UNION ALL
    SELECT 'Canadillo', 'Ephedra fragilis', 'flora', 'Arbusto', 'Roquedos, matorral seco y pie de acantilado en clima cálido', 'No amenazada', 'Arbusto de aspecto extraño: un manojo de tallos verdes, articulados y colgantes, casi sin hojas, que se quiebran con facilidad por los nudos. No es una planta con flores, sino un pariente lejano de las coníferas; sus semillas van envueltas en una cubierta roja y carnosa.', NULL, 'Tallos verdes articulados que se rompen por los nudos; Sin hojas visibles, solo escamas en cada nudo; Frutos rojos carnosos con una semilla dentro', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ephedra_fragilis_3.JPG?width=1280', 'User:falconaumanni (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie característica del matorral termomediterráneo semiárido (5330), sabinares (5210) y roquedos (8210) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia. Ficha básica (mínima), pendiente de ampliar.; IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Tracheophyta', 'Gnetopsida', 'Ephedrales', 'Ephedraceae', 'Ephedra', 'LC (Preocupación menor)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); frecuente en la Región', 'Ficha básica: especie característica del matorral semiárido y roquedos, frecuente en la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.', 4308, 2653414, NULL, NULL, NULL
    UNION ALL
    SELECT 'Ajo de flor oscura', 'Allium melananthum', 'flora', 'Planta bulbosa', 'Espartales, pastizales secos y claros de matorral sobre suelos margosos', 'Vulnerable', 'Ajo silvestre de flores de un púrpura tan oscuro que parece negro, agrupadas en una umbela apretada al final de un tallo largo y desnudo. Es un endemismo del sureste ibérico, de área muy reducida, que pasa el verano bajo tierra en forma de bulbo.', NULL, 'Flores de púrpura casi negro, muy oscuras; Umbela compacta sobre un tallo largo y liso; Huele a ajo al estrujar las hojas o el bulbo', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Allium_melananthum02.jpg?width=1280', 'Nanosanchez (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 5, NULL, 4, '{"categoria":"Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'nombre común alternativo "ajo de flor negra" según el PORN; IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Amaryllidaceae', 'Allium', 'NT (Casi amenazado)', 'No localizada en la Lista Roja de la Flora Vascular Española 2008 (pendiente de confirmar)', 'Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable', 'Foto localizada por búsqueda en Commons (no por el elemento de Wikidata del taxón): conviene confirmar que corresponde a esta especie. La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 2011, 2856202, NULL, NULL, NULL
    UNION ALL
    SELECT 'Aulaga', 'Launaea arborescens', 'flora', 'Mata', 'Matorral árido, ramblas y bordes de camino en clima muy seco', 'No amenazada', 'Mata en forma de bola formada por ramas verdes, rígidas y terminadas en pincho, casi sin hojas: la fotosíntesis la hacen los propios tallos. Al romper una rama suelta un látex blanco. Sus flores amarillas recuerdan a las del diente de león en miniatura.', NULL, 'Matorral redondo de ramas verdes y espinosas, casi sin hojas; Suelta látex blanco al partir un tallo; Flores amarillas tipo diente de león', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Launaea_arborescens_-_Oasis_Park_botanical_garden_-_Fuerteventura_-_02.jpg?width=1280', 'Norbert Nagel, Mörfelden-Walldorf, Germany (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie característica del matorral semiárido (hábitat 5330) y de los matorrales halo-nitrófilos (1430) según las Bases ecológicas preliminares (VVAA, MMARM, 2009) y las fichas de la Red Natura 2000; frecuente en la Región de Murcia (ficha de regmurcia.com). Sinónimo: Launaea spinosa. Ficha básica (mínima), pendiente de ampliar.', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Launaea', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de Flora Silvestre Protegida (Decreto 50/2003); frecuente en la Región', 'Ficha básica: especie característica del matorral semiárido, frecuente en la Región de Murcia. Presencia en el parque inferida del hábitat; pendiente de confirmación en campo y de ampliar la ficha.', 9623, 3144854, NULL, NULL, NULL
    UNION ALL
    SELECT 'Gato montés', 'Felis silvestris', 'fauna', 'Mamífero carnívoro', 'Bosque, matorral denso y roquedos con buena población de conejos y roedores', 'Interés especial', 'Gato salvaje europeo, más robusto que un gato doméstico atigrado, con la cola gruesa, roma en la punta y anillada de negro. Es solitario, esquivo y sobre todo nocturno. Su mayor amenaza es la hibridación con gatos asilvestrados, que diluye la población silvestre.', NULL, 'Cola gruesa, de punta roma y con anillos negros nítidos; Raya negra continua a lo largo del lomo; Aspecto más recio y patilargo que un gato casero', 'Todo el año (actividad crepuscular y nocturna)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Felis_silvestris_Kocka_divok%C3%A1_zoo_cropped.jpg?width=1280', 'Felis_silvestris_Kočka_divoká_ZOO_Děčín.jpg: Alena Houšková derivat… (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Mammalia', 'Carnivora', 'Felidae', 'Felis', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Hábitats 92/43/CEE, Anexo IV; Reglamento CITES (CE) 338/97, Anexo A', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial', 'El PORN cita la presencia de la especie en el parque sin detallar su categoría exacta de protección regional; pendiente de confirmar con el Catálogo Regional vigente. La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 12214, 7964291, NULL, NULL, NULL
    UNION ALL
    SELECT 'Gineta', 'Genetta genetta', 'fauna', 'Mamífero carnívoro', 'Bosque, matorral denso, roquedos y sotos con cobertura y refugios', 'Interés especial', 'Carnívoro esbelto de pelaje gris con manchas negras y una cola larguísima anillada en blanco y negro, tan larga como el resto del cuerpo. Es un trepador excelente y estrictamente nocturno. Deja sus excrementos en letrinas fijas sobre piedras y troncos, que usa durante años.', NULL, 'Cola muy larga con anillos blancos y negros bien marcados; Pelaje gris con hileras de manchas negras; Letrinas repetidas en el mismo punto elevado', 'Todo el año (actividad nocturna)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Genetta_genetta_felina_(Wroclaw_zoo).JPG?width=1280', 'Guérin Nicolas (messages) (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Mammalia', 'Carnivora', 'Viverridae', 'Genetta', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Hábitats 92/43/CEE, Anexo V', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial', 'El PORN cita la presencia de la especie en el parque sin detallar su categoría exacta de protección regional; pendiente de confirmar con el Catálogo Regional vigente. La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 11350, 5219362, NULL, NULL, NULL
    UNION ALL
    SELECT 'Garduña', 'Martes foina', 'fauna', 'Mamífero carnívoro', 'Roquedos, bosques, ruinas y construcciones rurales', 'No catalogada', 'Mustélido nocturno de cuerpo alargado y cola espesa, con un babero blanco en la garganta que suele bifurcarse hacia las patas delanteras. Trepa con soltura y aprovecha desde roquedos hasta desvanes. Es omnívora: come frutos, insectos, huevos y pequeños vertebrados.', NULL, 'Babero blanco en la garganta, a menudo dividido en dos; Excrementos retorcidos y con pelos o semillas, sobre piedras; Rastro nocturno; muy rara vez se ve de día', 'Todo el año (actividad nocturna)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Steinmarder_01.jpg?width=1280', 'Zefram (CC BY 2.0 de) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Mammalia', 'Carnivora', 'Mustelidae', 'Martes', 'LC', 'No incluida en el LESRPE ni en el Catálogo Español de Especies Amenazadas', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial', 'El IEPNB no registra figura estatal ni regional para esta especie. La categoría regional que figuraba procede del PORN y no se ha podido confirmar en la Ley 7/1995. La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 11289, 5218887, NULL, NULL, NULL
    UNION ALL
    SELECT 'Tejón', 'Meles meles', 'fauna', 'Mamífero carnívoro', 'Bosque, matorral y ribazos con suelo blando para excavar tejoneras', 'Interés especial', 'Mustélido corpulento y de patas cortas, con la cabeza blanca cruzada por dos bandas negras que pasan por los ojos. Excava madrigueras complejas —las tejoneras— que una misma familia amplía y usa durante generaciones. Es omnívoro y muy aficionado a las lombrices.', NULL, 'Cabeza blanca con dos franjas negras longitudinales; Tejoneras: varias bocas grandes con montones de tierra; Letrinas en hoyos poco profundos cerca de la madriguera', 'Todo el año (actividad nocturna)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Badger-badger.jpg?width=1280', 'BadgerHero (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia (Ley 7/1995): De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Mammalia', 'Carnivora', 'Mustelidae', 'Meles', 'LC', 'No incluida en el LESRPE ni en el Catálogo Español de Especies Amenazadas', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia (Ley 7/1995): De interés especial', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 11709, 2433875, NULL, NULL, NULL
    UNION ALL
    SELECT 'Sapo corredor', 'Epidalea calamita', 'fauna', 'Anfibio', 'Ramblas y zonas húmedas estacionales', 'Interés especial', 'Sapo de patas cortas que corre en vez de saltar, con una línea amarilla nítida a lo largo del centro del lomo. Se reproduce en charcas efímeras que se llenan con las lluvias, y los machos forman coros de un canto vibrante y estridente que se oye a kilómetros.', NULL, 'Raya amarilla continua por el centro del lomo; Corre a cuatro patas en vez de saltar; Canto nocturno vibrante y muy sonoro tras las lluvias', 'Otoño e invierno lluviosos', 'https://commons.wikimedia.org/wiki/Special:FilePath/Epidalea_calamita_02_by-dpc.jpg?width=1280', 'David Perez (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Amphibia', 'Anura', 'Bufonidae', 'Epidalea', 'LC', 'LESRPE; Directiva Hábitats 92/43/CEE, Anexo IV', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 24327, 2422507, NULL, NULL, NULL
    UNION ALL
    SELECT 'Azufaifo', 'Ziziphus lotus', 'flora', 'Arbusto', 'Matorrales arborescentes de Ziziphus', 'Hábitat prioritario UE / Vulnerable', 'Arbusto espinoso que forma cúpulas densas de varios metros, un microhábitat en sí mismo: bajo su copa se refugian aves, reptiles y mamíferos, y la humedad y el suelo son distintos que fuera. Sus ramas zigzaguean con dos espinas en cada nudo, una recta y otra ganchuda.', NULL, 'Ramas en zigzag con dos espinas por nudo, una recta y otra curva; Porte en cúpula o almohadón, muy denso; Frutos redondos que pasan de verde a pardo amarillento', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ziziphus_lotus_20200928_191923.jpg?width=1280', 'Nanosanchez (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 4, NULL, 4, '{"categoria":"Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'Directiva Hábitats 92/43/CEE, hábitat prioritario 5220*; Decreto 50/2003 (BORM), Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia; base científica: Sánchez Gómez et al. 2002, Libro Rojo de la Flora Silvestre Protegida de la Región de Murcia', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Rhamnaceae', 'Ziziphus', 'NE (no evaluada a nivel global)', 'Incluida en la Lista Roja de la Flora Vascular Española 2008 (categoría exacta pendiente de confirmar en listaroja.conservacionvegetal.org)', 'Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): Vulnerable', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 9441, 3039418, NULL, NULL, NULL
    UNION ALL
    SELECT 'Zamarrilla lanuda', 'Teucrium lanigerum', 'flora', 'Mata aromática', 'Matorral y cerros sobre suelos calizos y margosos secos', 'Interés especial', 'Mata cubierta por una lana blanca y espesa que la hace destacar en el matorral. Sus flores, rosadas o purpúreas, se agrupan en cabezuelas terminales y carecen de labio superior, con los estambres al descubierto. Es un endemismo del sureste ibérico.', NULL, 'Toda la planta cubierta de lana blanca y espesa; Flores sin labio superior, con los estambres asomando; Cabezuelas apretadas en el extremo de las ramas', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Teucrium_lanigerum_kz01.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado de protección', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Teucrium', 'NE', 'No localizada en la Lista Roja de la Flora Vascular Española 2008', 'Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 8809, 7308375, NULL, NULL, NULL
    UNION ALL
    SELECT 'Teucrio de Freyn', 'Teucrium freynii', 'flora', 'Mata aromática', 'Roquedos, pedregales y ramblas sobre suelos calizos secos', 'Interés especial', 'Teucrio endémico del sureste ibérico, de porte bajo y aspecto blanquecino, con hojas pequeñas y enrolladas y flores rosadas o blanquecinas sin labio superior. Como todas las labiadas, tiene el tallo de sección cuadrada y desprende aroma al frotarlo.', NULL, 'Flores sin labio superior, con los estambres asomando; Tallo de sección cuadrada, típico de labiada; Hojas pequeñas y enrolladas, de aspecto grisáceo', 'Primavera-verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Teucrium_freynii_kz01.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado de protección', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Teucrium', 'NE', 'No localizada en la Lista Roja de la Flora Vascular Española 2008', 'Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 8800, 3896744, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cuerno de cabra', 'Notoceras bicorne', 'flora', 'Hierba', 'Matorral árido y claros de vegetación', 'Interés especial', 'Crucífera anual y menuda, de tallos tendidos y hojas pequeñas, con flores blanquecinas poco vistosas. Lo característico son los frutos: pequeñas silículas rematadas por dos cuernecillos divergentes que le dan el nombre.', NULL, 'Frutos con dos cuernecillos divergentes en la punta; Planta anual diminuta y tendida por el suelo; Flores blanquecinas muy pequeñas, casi inapreciables', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Notoceras_bicorne_kz08.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado de protección', 'Tracheophyta', 'Magnoliopsida', 'Brassicales', 'Brassicaceae', 'Notoceras', 'NE', 'No localizada en la Lista Roja de la Flora Vascular Española 2008', 'Catálogo Regional de Flora Silvestre Protegida de Murcia (Decreto 50/2003): De interés especial', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 6625, 5374288, NULL, NULL, NULL
    UNION ALL
    SELECT 'Bolina', 'Genista cinerea', 'flora', 'Arbusto', 'Matorral y laderas soleadas de montaña media, sobre suelos calizos', 'NE', 'Retama de ramas finas, sedosas y de un verde grisáceo, sin espinas, que en floración se cubre de flores amarillas fragantes. Sus hojas son diminutas y caen pronto: la fotosíntesis la hacen los tallos.', NULL, 'Ramas finas y flexibles, sin espinas; Aspecto grisáceo por los pelos sedosos de las ramillas; Floración amarilla abundante y perfumada', 'Primavera y principio de verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Genista_cinerea26de_maig_2007_019.jpg?width=1280', 'Victor M. Vicente Selvas (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 4090, 5210, 5330; GBIF (90 ocurrencias en 7 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Genista', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 4883, 5347718, NULL, NULL, NULL
    UNION ALL
    SELECT 'Mimbre', 'Salix pedicellata', 'flora', 'Árbol', 'Riberas, fuentes y cauces con humedad permanente', 'LC', 'Sauce mediterráneo de porte arbustivo o de arbolillo, con hojas alargadas verdes por encima y algo blanquecinas por debajo. Florece antes de echar la hoja, en amentos peludos. Forma parte de las orlas de vegetación que fijan las márgenes de los cauces.', NULL, 'Amentos peludos en las ramas desnudas, antes que las hojas; Hojas alargadas, más pálidas por el envés; Siempre junto a agua o en suelos con humedad permanente', 'Primavera (floración) y todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Salix_pedicellata_Habitus_2009-9-27_CampoCalatrava.jpg?width=1280', 'javier martin (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 92A0; GBIF (44 ocurrencias en 6 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Malpighiales', 'Salicaceae', 'Salix', 'LC (Preocupación menor) (evaluación UICN 2010)', 'Sin figura de protección nacional específica registrada en EIDOS', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 7898, 5583320, NULL, NULL, NULL
    UNION ALL
    SELECT 'Alagua', 'Genista longipes', 'flora', 'Arbusto', 'Crestas, pedregales y matorral almohadillado de montaña', 'NE', 'Genista espinosa que forma cojines densos y bajos, adaptados al viento y al frío de las cumbres. Sus flores amarillas salen sobre pedúnculos largos, un rasgo que le da el nombre. Es un endemismo del sureste ibérico.', NULL, 'Cojín compacto y espinoso, muy bajo; Flores amarillas sobre pedúnculos largos y finos; En crestas y pedregales de montaña, expuesta al viento', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Genista-longipes-2019.jpg?width=1280', 'MottaW (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 4090; GBIF (37 ocurrencias en 5 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Genista', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 4899, 5347560, NULL, NULL, NULL
    UNION ALL
    SELECT 'bulbocodio de primavera', 'Colchicum triphyllum', 'flora', 'Planta bulbosa', 'Pastizales y claros de matorral en montaña, sobre suelos pedregosos', 'NE', 'Bulbosa que florece muy pronto, a veces con la nieve aún cerca, sacando del suelo flores rosadas o lilas en forma de copa junto a tres hojas estrechas. El resto del año permanece bajo tierra. Toda la planta es tóxica, como el resto del género.', NULL, 'Flores rosa lila en copa, casi a ras de suelo; Tres hojas estrechas acompañando a la flor; Florece muy temprano, antes que la mayoría del pastizal', 'Final de invierno y principio de primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Colchicum_triphyllum_001_GotBot_2016.jpg?width=1280', 'Averater (CC BY 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 6220; GBIF (30 ocurrencias en 8 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Liliopsida', 'Liliales', 'Colchicaceae', 'Colchicum', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 3495, 2739870, NULL, NULL, NULL
    UNION ALL
    SELECT 'Rabo de gato', 'Sideritis leucantha', 'flora', 'Mata aromática', 'Tomillares y matorral raso sobre suelos calizos y margosos', 'LC', 'Rabogato de tallos erguidos cubiertos de pelusa blanca, con flores de color blanco crema dispuestas en verticilos separados a lo largo de la espiga. Es un endemismo del sureste ibérico y una de las plantas usadas tradicionalmente en infusión.', NULL, 'Flores blanco crema en anillos separados por el tallo; Toda la planta blanquecina y algo lanuda; Brácteas anchas y punzantes bajo cada grupo de flores', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Alb-S.leucantha-13.jpg?width=1280', 'Philmarin (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 5330; GBIF (23 ocurrencias en 6 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Sideritis', 'LC (Preocupación menor) (evaluación UICN 2014)', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 8340, 7307627, NULL, NULL, NULL
    UNION ALL
    SELECT 'Ononis ornithopodioides', 'Ononis ornithopodioides', 'flora', 'Hierba', 'Pastizales anuales y claros de matorral sobre suelos secos', 'NE', 'Pequeña leguminosa anual de tallos finos y glandulosos, con hojas de tres foliolos y flores amarillas diminutas. Sus legumbres, curvadas y dispuestas en grupo, recuerdan a los dedos de una pata de pájaro, lo que le da el nombre científico.', NULL, 'Legumbres curvas agrupadas, como una pata de ave; Flores amarillas muy pequeñas; Tallos pegajosos al tacto, con pelos glandulosos', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ononis_ornithopodioides_kz1.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 6220; GBIF (19 ocurrencias en 6 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Ononis', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 6696, 2977204, NULL, NULL, NULL
    UNION ALL
    SELECT 'Jara blanca', 'Cistus atriplicifolius', 'flora', 'Mata', 'Matorral y jarales sobre suelos secos y soleados de montaña media', 'NE', 'Arbusto de hojas anchas, ovaladas y cubiertas de una pelusa plateada que le da un aspecto casi blanco. En primavera se llena de flores amarillas de cinco pétalos con una mancha oscura en la base. Es un endemismo del sur y sureste peninsular.', NULL, 'Hojas anchas y plateadas, no estrechas como las jaras; Flores amarillas con una manchita oscura en la base del pétalo; Porte erguido, más alto que las jarillas comunes', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Halimium_commutatum1.jpg?width=1280', 'Ximenex (CC BY-SA 2.1 es) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 5330; GBIF (19 ocurrencias en 5 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28. Nombre aceptado en EIDOS; Halimium atriplicifolium es sinónimo.', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Cistus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 5037, 7331286, NULL, NULL, NULL
    UNION ALL
    SELECT 'Rascavieja', 'Ononis speciosa', 'flora', 'Arbusto', 'Matorral seco y laderas soleadas sobre suelos pedregosos', 'NE', 'Leguminosa arbustiva y pegajosa, con hojas de tres foliolos y racimos densos y erguidos de flores de un amarillo intenso. Es un endemismo del sur peninsular y del norte de África, y una de las plantas más vistosas del matorral en plena floración.', NULL, 'Racimos densos y erguidos de flores amarillo vivo; Toda la planta pegajosa por los pelos glandulosos; Hojas de tres foliolos dentados', 'Primavera', 'https://inaturalist-open-data.s3.amazonaws.com/photos/184117054/original.jpeg', 'Santiago Martín-Bravo (CC BY 4.0) · iNaturalist/GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 9560; GBIF (19 ocurrencias en 7 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Ononis', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 6712, 2977276, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cosentinia vellea', 'Cosentinia vellea', 'flora', 'Helecho', 'Grietas de roquedos secos y soleados, paredones y pedregales', 'NE', 'Helecho pequeño cubierto por completo de una densa lana parda que le da aspecto afieltrado y le permite sobrevivir en roca seca y al sol. En sequía se enrolla sobre sí mismo hasta parecer muerto, y se despliega en cuanto llueve.', NULL, 'Frondes cubiertas de lana parda, aspecto afieltrado; Se enrolla en verano y revive con la lluvia; En roca seca y soleada, no en umbrías húmedas', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cosentinia_vellea_kz02.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 8210; GBIF (18 ocurrencias en 4 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Polypodiopsida', 'Polypodiales', 'Pteridaceae', 'Cosentinia', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 3758, 7335582, NULL, NULL, NULL
    UNION ALL
    SELECT 'Clujía', 'Bupleurum gibraltarium', 'flora', 'Arbusto', 'Roquedos, laderas pedregosas y matorral seco sobre calizas', 'NE', 'Umbelífera leñosa, algo insólita en una familia de hierbas, con hojas estrechas, coriáceas y de un verde azulado. Sus umbelas de flores amarillas se abren en pleno verano. Desprende un olor resinoso característico al romper una rama.', NULL, 'Umbelífera con base leñosa, no herbácea; Hojas estrechas, duras y de verde azulado; Umbelas amarillas en pleno verano', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/B._gibraltarium-1.JPG?width=1280', 'Philmarin (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 9560; GBIF (17 ocurrencias en 5 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28. Nombre aceptado en EIDOS; Bupleurum gibraltaricum es sinónimo.', 'Tracheophyta', 'Magnoliopsida', 'Apiales', 'Apiaceae', 'Bupleurum', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 2843, 3638706, NULL, NULL, NULL
    UNION ALL
    SELECT 'Botón azul', 'Jasione foliosa', 'flora', 'Hierba', 'Fisuras y repisas de roquedos calizos de montaña', 'NE', 'Planta rupícola que forma matas compactas en las grietas de la roca, con cabezuelas globosas de flores azules formadas por muchas florecillas estrechas. Es un endemismo ibérico ligado a los cantiles calizos, donde escapa de la competencia y del ganado.', NULL, 'Cabezuelas azules redondas, como pompones; Crece encajada en grietas de pared rocosa; Hojas estrechas agrupadas en la base', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Jasione_foliosa_var._Minuta_GotBot_2015_001.jpg?width=1280', 'Averater (CC BY 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 8210; GBIF (16 ocurrencias en 5 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Campanulaceae', 'Jasione', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 5441, 3165691, NULL, NULL, NULL
    UNION ALL
    SELECT 'Encina', 'Quercus ilex', 'flora', 'Árbol', 'Bosques y matorrales mediterráneos sobre suelos variados, en clima no extremo', 'LC', 'Árbol perennifolio de copa densa y redondeada, con hojas coriáceas verde oscuro por el haz y blanquecinas y afieltradas por el envés. Las hojas jóvenes y las de las ramas bajas tienen el borde espinoso, un mecanismo de defensa frente a los herbívoros.', NULL, 'Envés de la hoja blanquecino y afieltrado; Hojas de las ramas bajas con borde espinoso; Copa densa y oscura, muy cerrada a la luz', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Carrasca_de_la_Raboseras.JPG?width=1280', 'Picamaderos (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 5210, 9340; GBIF (15 ocurrencias en 5 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fagales', 'Fagaceae', 'Quercus', 'LC (Preocupación menor) (evaluación UICN 2020)', 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO I. Lista de especies forestales e híbiridos artificiales (Real Decreto 289/2003, de 7 de marzo, sobre la comercialización de los materiales forestal…)', 'En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 7483, 2879098, NULL, NULL, NULL
    UNION ALL
    SELECT 'Retama de escobas', 'Cytisus scoparius', 'flora', 'Arbusto', 'Claros de bosque, laderas y taludes sobre suelos silíceos o descarbonatados', 'NE', 'Arbusto de ramas verdes, angulosas y flexibles, casi sin hojas, que en primavera se cubre de flores amarillas grandes. Sus legumbres, negras al madurar, se abren con un chasquido audible en los días secos y lanzan las semillas a varios metros.', NULL, 'Ramas verdes de sección angulosa, flexibles; Legumbres negras y peludas en los bordes; Las vainas estallan con un chasquido en verano', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cytisus_scoparius_by_Danny_S._-_001.JPG?width=1280', 'Danny S. (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 5330; GBIF (15 ocurrencias en 7 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Cytisus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'CEEEI: Incluido (Real Decreto 630/2013, de 2 de agosto, por el que se regula el Catálogo español de especies exóticas invasoras. BOE 185 de 3 de agosto de 2013)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 3942, 5354656, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cisca', 'Imperata cylindrica', 'flora', 'Gramínea', 'Arenales, ramblas y suelos húmedos con capa freática cercana', 'NE', 'Gramínea perenne que se extiende por rizomas y levanta espigas cilíndricas de un blanco plateado y sedoso, muy vistosas a contraluz. Coloniza arenales y bordes de rambla, donde ayuda a fijar el sustrato suelto.', NULL, 'Espigas cilíndricas de un blanco sedoso brillante; Se extiende en manchas por rizomas subterráneos; Hojas rígidas con el nervio central pálido y marcado', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Impera_cylind_071122-1339_stgd.jpg?width=1280', 'W.A. Djatmiko (Wie146) (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 92D0; GBIF (15 ocurrencias en 5 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Imperata', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Incluido (Real Decreto 216/2019, de 29 de marzo, por el que se aprueba la lista de especies exóticas…)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 10055, 8424006, NULL, NULL, NULL
    UNION ALL
    SELECT 'Saxifraga almeriensis', 'Saxifraga camposii subsp. leptophylla', 'flora', 'Hierba', 'Grietas y repisas umbrías de roquedos calizos de montaña', 'NE', 'Saxífraga rupícola que forma pequeñas rosetas de hojas carnosas y algo divididas encajadas en la roca, con tallos finos rematados en flores blancas de cinco pétalos. Es un endemismo del sureste ibérico restringido a unas pocas sierras.', NULL, 'Rosetas pequeñas y carnosas metidas en la fisura; Flores blancas de cinco pétalos sobre tallos finos; Casi siempre en paredes umbrías y frescas', 'Primavera', 'https://inaturalist-open-data.s3.amazonaws.com/photos/111644731/original.jpeg', 'faluke (CC BY-NC 4.0) · GBIF/iNaturalist', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 8210; GBIF (15 ocurrencias en 5 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28. Nombre aceptado en EIDOS; Saxifraga almeriensis es sinónimo.', 'Tracheophyta', 'Magnoliopsida', 'Saxifragales', 'Saxifragaceae', 'Saxifraga', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 7997, 3753971, NULL, NULL, NULL
    UNION ALL
    SELECT 'erguen', 'Cytisus lanigerus', 'flora', 'Arbusto', 'Matorral y laderas soleadas sobre suelos secos y pedregosos', 'NE', 'Arbusto espinoso y muy ramificado que en primavera se cubre por completo de flores amarillas. Sus ramas terminan en espinas fuertes y sus legumbres van cubiertas de pelos sedosos. Forma masas impenetrables que dan refugio a aves de matorral.', NULL, 'Ramas rematadas en espinas rígidas y punzantes; Floración amarilla masiva que cubre toda la mata; Legumbres cubiertas de pelos blancos y sedosos', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Calycotome_villosa1.jpg?width=1280', 'Ximenex (CC BY-SA 2.1 es) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 9560; GBIF (12 ocurrencias en 6 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28. Nombre aceptado en EIDOS; Calicotome villosa es sinónimo.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Cytisus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 2953, 2956364, NULL, NULL, NULL
    UNION ALL
    SELECT 'campanilla espigada', 'Convolvulus lineatus', 'flora', 'Hierba', 'Pastizales secos, ribazos y claros de matorral sobre suelos margosos', 'NE', 'Correhuela de porte bajo y no trepadora, con hojas estrechas cubiertas de pelos sedosos que las hacen brillar con una pátina plateada. Sus flores son embudos rosados o blanquecinos que se abren por la mañana y se cierran con el calor.', NULL, 'Hojas estrechas con brillo sedoso plateado; No trepa: forma matitas bajas y extendidas; Flores en embudo, rosadas o casi blancas', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Convolvulus_lineatus_2.jpg?width=1280', 'Ghislain118 https://www.fleurs-des-montagnes.net (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 6220; GBIF (10 ocurrencias en 8 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Solanales', 'Convolvulaceae', 'Convolvulus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 3702, 3677112, NULL, NULL, NULL
    UNION ALL
    SELECT 'campanillas de cantil', 'Campanula rotundifolia subsp. hispanica', 'flora', 'Hierba', 'Fisuras de roquedos, taludes y pedregales de montaña', 'NE', 'Campánula de tallos finos y flexibles con flores azul violeta en forma de campana colgante. Crece en grietas de roca y en pedregales, donde sus raíces alcanzan la humedad que retiene la piedra. Las hojas de la base tienen forma redondeada y las del tallo son estrechas.', NULL, 'Flores azuladas en campana, colgando del tallo; Hojas basales redondeadas, muy distintas de las del tallo; En grietas y repisas de roca, a menudo colgando', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Campanula_hispanica_1.jpg?width=1280', 'Ghislain118 http://www.fleurs-des-montagnes.net (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 8210; GBIF (10 ocurrencias en 5 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28. Nombre aceptado en EIDOS; Campanula hispanica es sinónimo.', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Campanulaceae', 'Campanula', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'No incluida en el LESRPE ni en el Catálogo Español de Especies Amenazadas [IEPNB, Lista Patrón de las especies silvestres presentes en España, vista de normas, consultada 2026-08-09]', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 3013, 5411288, NULL, NULL, NULL
    UNION ALL
    SELECT 'Pampajarito', 'Sedum gypsicola', 'flora', 'Planta suculenta', 'Litosuelos, costras yesosas y repisas rocosas secas', 'NE', 'Crasulácea diminuta de hojas cilíndricas y carnosas apretadas contra el tallo, que forma almohadillas sobre suelos yesosos y roca desnuda. En verano toma tonos rojizos y saca flores blancas estrelladas.', NULL, 'Hojitas carnosas y cilíndricas apretadas al tallo; Vira a rojizo con la sequía y el sol; Flores blancas estrelladas de cinco pétalos', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sedum_gypsicola_kz01.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 6110; GBIF (9 ocurrencias en 7 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Saxifragales', 'Crassulaceae', 'Sedum', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 8208, 8213145, NULL, NULL, NULL
    UNION ALL
    SELECT 'Tojo', 'Ulex europaeus', 'flora', 'Arbusto', 'Matorral sobre suelos ácidos y frescos, claros y bordes de camino', 'LC', 'Arbusto totalmente cubierto de espinas rígidas —hojas y ramillas transformadas— que en invierno y primavera se llena de flores amarillas con olor a coco. Forma masas impenetrables que sirven de refugio a pájaros de matorral.', NULL, 'Espinas rígidas por toda la planta, muy punzantes; Flores amarillas con aroma dulce, a coco; Florece en pleno invierno, adelantándose al resto', 'Invierno y primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ulex_europaeus.jpg?width=1280', 'J.F. Gaffard Jeffdelonge at fr.wikipedia (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 4090; GBIF (8 ocurrencias en 6 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Ulex', 'LC (Preocupación menor) (evaluación UICN 2017)', 'CEEEI: Incluido (Real Decreto 630/2013, de 2 de agosto, por el que se regula el Catálogo español de especies exóticas invasoras. BOE 185 de 3 de agosto de 2013)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 9130, 2951984, NULL, NULL, NULL
    UNION ALL
    SELECT 'Madreselva mediterránea', 'Lonicera biflora', 'flora', 'Arbusto', 'Roquedos, matorral denso y barrancos cálidos', 'NE', 'Madreselva de tallos trepadores o apoyantes y hojas opuestas algo carnosas, con flores blanquecinas agrupadas de dos en dos, de donde le viene el nombre. Sus frutos son bayas rojas o negruzcas que consumen las aves.', NULL, 'Flores agrupadas por parejas en la axila de la hoja; Hojas opuestas, a veces soldadas por la base; Tallos que se apoyan y trepan sobre otros arbustos', 'Primavera', 'https://inaturalist-open-data.s3.amazonaws.com/photos/527297838/original.jpg', 'Finlay F. K. Thorpe (CC BY-NC 4.0) · GBIF/iNaturalist', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 92D0; GBIF (7 ocurrencias en 4 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Dipsacales', 'Caprifoliaceae', 'Lonicera', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 6035, 5598704, NULL, NULL, NULL
    UNION ALL
    SELECT 'Linaria cavanillesii', 'Linaria cavanillesii', 'flora', 'Hierba', 'Repisas y fisuras de cantiles calizos, generalmente en umbría', 'NE', 'Linaria rupícola de tallos colgantes y hojas algo carnosas y verticiladas, con flores amarillas provistas de un espolón largo y curvado. Es un endemismo ibérico de área muy reducida, restringido a un puñado de cantiles.', NULL, 'Tallos colgando de la pared rocosa; Flores amarillas con espolón largo por detrás; Hojas dispuestas en anillos alrededor del tallo', 'Primavera y verano', 'https://inaturalist-open-data.s3.amazonaws.com/photos/501474709/original.jpeg', 'deutschle (CC BY-NC 4.0) · GBIF/iNaturalist', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 8210; GBIF (6 ocurrencias en 3 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Plantaginaceae', 'Linaria', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 5785, 8106135, NULL, NULL, NULL
    UNION ALL
    SELECT 'Trebillos', 'Trifolium gemellum', 'flora', 'Hierba', 'Pastizales anuales sobre suelos arenosos y ácidos', 'NE', 'Trébol anual diminuto, de tallos tendidos y cabezuelas pequeñas y peludas que a menudo salen emparejadas, de donde le viene el nombre. Forma parte de los pastizales efímeros que se secan en cuanto llega el calor.', NULL, 'Cabezuelas pequeñas y peludas, con frecuencia de dos en dos; Planta anual y menuda, tendida por el suelo; Hojas de tres foliolos, típicas de trébol', 'Primavera', 'https://inaturalist-open-data.s3.amazonaws.com/photos/601798690/original.jpg', 'Miguel A. Casado (CC BY-NC 4.0) · GBIF/iNaturalist', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 6220; GBIF (5 ocurrencias en 5 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Trifolium', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 8989, 5358856, NULL, NULL, NULL
    UNION ALL
    SELECT 'Erodium foetidum', 'Erodium foetidum', 'flora', 'Hierba', 'Grietas y repisas de roquedos calizos', 'LC', 'Geranio rupícola que forma rosetas de hojas recortadas y algo pegajosas, con flores blancas o rosadas veteadas. Como todos los erodios, sus frutos rematan en un pico largo que se enrosca al secarse y va clavando la semilla en las grietas.', NULL, 'Rosetas de hojas recortadas encajadas en la roca; Frutos con pico largo que se enrosca en espiral; Olor desagradable al estrujar las hojas', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/ERODIUM_FOETIDUM_-_S%C3%92BOL_-_IB-784_(Cargola_de_roca).jpg?width=1280', 'Isidre blanc (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 5, '{"categoria":"CEEA: En peligro de extinción (Orden AAA/1771/2015, de 31 de agosto, por la que se modifica el anexo del Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 211, de 3 de septiembre de 2015)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"CEEA: En peligro de extinción (Orden AAA/1771/2015, de 31 de agosto, por la que se modifica el anexo del Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 211, de 3 de septiembre de 2015)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 4090, 6170; GBIF (5 ocurrencias en 5 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Geraniales', 'Geraniaceae', 'Erodium', 'LC (Preocupación menor) (evaluación UICN 2014)', 'CEEA: En peligro de extinción (Orden AAA/1771/2015, de 31 de agosto, por la que se modifica el anexo del Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 211, de 3 de septiembre de 2015)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 9837, 9368145, NULL, NULL, NULL
    UNION ALL
    SELECT 'Tomillo', 'Thymus antoninae', 'flora', 'Mata aromática', 'Tomillares y pastizales pedregosos de montaña sobre calizas', 'NE', 'Tomillo endémico del sureste ibérico, de área muy restringida, que forma matitas bajas y grisáceas con espigas de flores rosadas o blanquecinas. Su rareza y la fragmentación de su hábitat lo convierten en una de las plantas más vulnerables del grupo.', NULL, 'Mata baja y grisácea, de hojas muy pequeñas; Espigas cortas de flores rosadas o blancas; Aroma a tomillo, más suave que el de sus parientes comunes', 'Primavera y verano', 'https://inaturalist-open-data.s3.amazonaws.com/photos/411356756/original.jpeg', 'Maël Taupin (CC BY-NC 4.0) · GBIF/iNaturalist', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 5330; GBIF (5 ocurrencias en 5 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Thymus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', 'Foto localizada por búsqueda en Commons (no por el elemento de Wikidata del taxón): conviene confirmar que corresponde a esta especie.', 8896, 5607746, NULL, NULL, NULL
    UNION ALL
    SELECT 'Quejigueta', 'Quercus lusitanica', 'flora', 'Arbusto', 'Matorral y claros de bosque sobre suelos silíceos o descarbonatados', 'LC', 'Roble enano que rara vez supera el medio metro y se extiende por rizomas formando manchas. Sus hojas son pequeñas, dentadas y algo coriáceas, y las bellotas, diminutas. Es un arbusto, no un árbol joven: nunca llega a levantar tronco.', NULL, 'Porte muy bajo, casi rastrero, en manchas extensas; Hojas pequeñas y dentadas, algo rígidas; Bellotas muy pequeñas, casi sentadas en la rama', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Quercus_lusitanica_kz01.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 5330; GBIF (5 ocurrencias en 5 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fagales', 'Fagaceae', 'Quercus', 'LC (Preocupación menor) (evaluación UICN 2018)', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 7381, 2881060, NULL, NULL, NULL
    UNION ALL
    SELECT 'Rabo de gato', 'Sideritis bourgaeana', 'flora', 'Mata aromática', 'Tomillares y matorral raso sobre suelos calizos secos', 'NE', 'Rabogato de tallos blanquecinos y flores agrupadas en verticilos separados, característico del sureste ibérico. Es un taxón raro y poco fotografiado: como otras labiadas del grupo, se ha usado tradicionalmente en infusiones.', NULL, 'Tallos y hojas cubiertos de pelusa blanca; Flores en anillos bien separados a lo largo del tallo; Brácteas anchas y algo punzantes bajo cada verticilo', 'Primavera y verano', NULL, NULL, NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO), especies características del/de los HIC 5330; GBIF (5 ocurrencias en 5 hábitats del parque, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Sideritis', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', 'Sin foto: no existe ninguna imagen con licencia libre de este taxón ni en Wikimedia Commons ni en GBIF (0 ocurrencias con multimedia). La ficha muestra la portada temática hasta conseguir una fotografía propia.', 8279, 3892179, NULL, NULL, NULL
    UNION ALL
    SELECT 'Jara blanca', 'Cistus albidus', 'flora', 'Mata', 'Matorral y laderas soleadas sobre suelos calizos secos', 'NE', 'Jara de hojas blanquecinas, aterciopeladas al tacto y sin peciolo, con flores grandes de color rosa malva y pétalos arrugados como papel de seda que duran solo unas horas. Es una de las plantas que da color al matorral en primavera.', NULL, 'Hojas blanquecinas y aterciopeladas, sentadas en la rama; Flores rosa malva grandes, de pétalos arrugados; Cada flor dura apenas una mañana', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cistus_albidus_flowers.jpg?width=1280', 'Júlio Reis (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (549 ocurrencias en 10 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Cistus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 3609, 7331435, NULL, NULL, NULL
    UNION ALL
    SELECT 'Enebro de la miera', 'Juniperus oxycedrus', 'flora', 'Conífera', 'Matorral, pinares aclarados y laderas pedregosas', 'LC', 'Enebro de hojas aciculares y punzantes dispuestas de tres en tres, con dos bandas blancas en la cara superior que lo separan a simple vista de la sabina. Sus gálbulos son rojizos al madurar. De su madera se destilaba el aceite de miera.', NULL, 'Hojas punzantes en grupos de tres, no en escama; Dos rayas blancas en la cara superior de cada hoja; Gálbulos rojizos y brillantes al madurar', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Juniperus_oxycedrus_g1.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (482 ocurrencias en 10 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Pinopsida', 'Pinales', 'Cupressaceae', 'Juniperus', 'LC (Preocupación menor) (evaluación UICN 2013)', 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO XII. Especies a las que se refiere la disposición adicional tercera (otras especies forestales importantes para la selvicultura en España) (Real Decreto 289/2003, de 7 de marzo, sobre la comercialización de los materiales forestal…)', 'En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…); Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 5505, 2684451, NULL, NULL, NULL
    UNION ALL
    SELECT 'Carrasca', 'Quercus rotundifolia', 'flora', 'Árbol', 'Bosques y matorrales mediterráneos continentales, sobre suelos secos y pobres', 'LC', 'La encina de interior, más adaptada al frío y a la sequía continental, con hojas más redondeadas y bellotas dulces. A menudo crece en mata por el efecto del ramoneo y las cortas repetidas. Muchos autores la consideran una subespecie de la encina.', NULL, 'Hojas más redondeadas y pequeñas que las de la encina litoral; Bellotas de sabor dulce, no amargas; Frecuente en porte de mata, con varios pies', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Carrasca_de_la_Raboseras.JPG?width=1280', 'Picamaderos (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (187 ocurrencias en 9 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fagales', 'Fagaceae', 'Quercus', 'LC (Preocupación menor) (evaluación UICN 2018)', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 7379, 2881550, NULL, NULL, NULL
    UNION ALL
    SELECT 'Aliaga', 'Erinacea anthyllis', 'flora', 'Mata', 'Crestas ventosas, pastizales pedregosos y matorral almohadillado de montaña', 'NE', 'Leguminosa que forma cojines rígidos y espinosos, una arquitectura que le permite resistir el viento, el frío y el pisoteo en las cumbres. En primavera se cubre de flores azul violeta que contrastan con el verde grisáceo de las espinas.', NULL, 'Cojín compacto y espinoso, duro al tacto; Flores azul violeta sobre un almohadón de espinas; En crestas y collados expuestos al viento', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/ERINACEA_ANTHYLLIS_-_SANT_MAMET.JPG?width=1280', 'Isidre blanc (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (162 ocurrencias en 9 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Erinacea', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 4238, 2977757, NULL, NULL, NULL
    UNION ALL
    SELECT 'Tomillo blanco', 'Thymus membranaceus', 'flora', 'Mata aromática', 'Tomillares y matorral raso sobre suelos calizos secos', 'NE', 'Tomillo endémico del sureste ibérico, fácil de reconocer por unas brácteas grandes, blancas y membranosas que rodean la inflorescencia y parecen pétalos. Ese conjunto vistoso, más que las flores en sí, es lo que atrae a los insectos.', NULL, 'Brácteas blancas grandes y papiráceas rodeando la flor; Cabezuelas terminales muy vistosas y redondeadas; Aroma intenso a tomillo al frotar', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Thymus_membranaceus_(3).jpg?width=1280', 'Nanosanchez (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (147 ocurrencias en 10 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Thymus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 8931, 7306992, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cornicabra', 'Pistacia terebinthus', 'flora', 'Arbusto', 'Barrancos, umbrías y matorral alto sobre suelos frescos', 'LC', 'Arbusto o arbolillo de hoja caduca, con hojas compuestas de foliolos grandes y brillantes y un raquis sin alas, lo que lo separa del lentisco. Suele presentar agallas rojizas y curvadas en forma de cuerno, provocadas por pulgones, que le dan el nombre.', NULL, 'Agallas rojizas curvadas como cuernos en las hojas; Pierde la hoja en invierno, al contrario que el lentisco; Hoja compuesta con foliolo terminal y raquis sin alas', 'Primavera a otoño (pierde la hoja en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pistachier2.JPG?width=1280', 'greffer.net (CC BY 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (142 ocurrencias en 11 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Sapindales', 'Anacardiaceae', 'Pistacia', 'LC (Preocupación menor) (evaluación UICN 2016)', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 7130, 3190580, NULL, NULL, NULL
    UNION ALL
    SELECT 'Durillo', 'Viburnum tinus', 'flora', 'Arbusto', 'Umbrías, barrancos y sotobosque de encinar y pinar húmedo', 'LC', 'Arbusto de hojas perennes, opuestas y coriáceas, que florece en pleno invierno con corimbos de flores blancas nacidas de capullos rosados. Sus frutos son bayas de un azul metálico oscuro muy llamativo.', NULL, 'Florece en invierno, en corimbos blancos planos; Capullos rosados antes de abrir; Frutos azul metálico oscuro, casi negros', 'Invierno y primavera (floración)', 'https://commons.wikimedia.org/wiki/Special:FilePath/T2_37_Viburnum_tinus_par_Pierre-Joseph_Redout%C3%A9.jpeg?width=1280', 'Pierre-Joseph Redouté (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (136 ocurrencias en 8 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Dipsacales', 'Adoxaceae', 'Viburnum', 'LC (Preocupación menor) (evaluación UICN 2018)', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 9370, 2888585, NULL, NULL, NULL
    UNION ALL
    SELECT 'Pino rodeno', 'Pinus pinaster', 'flora', 'Conífera', 'Laderas y sierras sobre suelos silíceos o arenosos, en clima algo húmedo', 'LC', 'Pino de acículas largas, gruesas y rígidas, las mayores de los pinos ibéricos, y piñas grandes y brillantes con escamas terminadas en pincho. Su corteza, gruesa y profundamente agrietada, muestra tonos rojizos en el fondo de las grietas.', NULL, 'Acículas muy largas y gruesas, que pinchan al apretarlas; Piñas grandes y brillantes con escamas apuntadas; Corteza muy gruesa y agrietada, rojiza por dentro', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pinus_pinaster_20131229.jpg?width=1280', 'Luis Fernández García (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (99 ocurrencias en 9 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Pinopsida', 'Pinales', 'Pinaceae', 'Pinus', 'LC (Preocupación menor) (evaluación UICN 2013)', 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO I. Lista de especies forestales e híbiridos artificiales (Real Decreto 289/2003, de 7 de marzo, sobre la comercialización de los materiales forestal…)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 7123, 5285565, NULL, NULL, NULL
    UNION ALL
    SELECT 'Ardilla roja', 'Sciurus vulgaris', 'fauna', 'Roedor', 'Pinares y bosques con arbolado maduro y producción de piñones o frutos', 'LC', 'Ardilla arborícola de cola larga y esponjosa y orejas con pinceles de pelo más marcados en invierno. En los pinares mediterráneos su rastro más evidente son las piñas roídas hasta dejar solo el eje, abandonadas en tocones y piedras.', NULL, 'Piñas roídas hasta el raspón, apiladas en un mismo posadero; Cola larga y esponjosa que mantiene erguida al saltar; Pinceles de pelo en las orejas, sobre todo en invierno', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Eichh%C3%B6rnchen_D%C3%BCsseldorf_Hofgarten_edit.jpg?width=1280', 'Ray eye (CC BY-SA 2.0 de) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (97 ocurrencias en 8 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Chordata', 'Mammalia', 'Rodentia', 'Sciuridae', 'Sciurus', 'LC (Preocupación menor) (evaluación UICN 2023)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 12414, 8211070, NULL, NULL, NULL
    UNION ALL
    SELECT 'Yerbatú', 'Peucedanum officinale', 'flora', 'Hierba', 'Herbazales, claros de matorral y bordes de bosque sobre suelos profundos', 'NE', 'Umbelífera robusta que levanta tallos de más de un metro rematados en grandes umbelas de flores amarillas. Sus hojas están divididas muchas veces en segmentos estrechos y largos. Es planta nutricia de varias mariposas.', NULL, 'Umbelas amarillas amplias sobre tallos altos; Hojas divididas en segmentos muy finos y largos; Cepa gruesa y leñosa en la base', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Raskovnik33Joe-Laserpitium_siler.JPG?width=1280', 'Струјајое (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (92 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Apiales', 'Apiaceae', 'Peucedanum', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 7065, 6026255, NULL, NULL, NULL
    UNION ALL
    SELECT 'Vidriera', 'Digitalis obscura', 'flora', 'Mata', 'Matorral, pedregales y laderas soleadas sobre suelos calizos', 'NE', 'Dedalera leñosa en la base, con hojas estrechas, brillantes y de borde entero, muy distinta de las digitales de hoja ancha. Sus flores son tubos colgantes de un naranja rojizo con manchas oscuras en el interior. Toda la planta es tóxica.', NULL, 'Flores en dedal de color naranja rojizo; Hojas estrechas, lustrosas y de borde liso; Base leñosa, no herbácea', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Digitalis_obscura_1.jpg?width=1280', 'Cillas (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (86 ocurrencias en 8 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Plantaginaceae', 'Digitalis', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 4047, 5559052, NULL, NULL, NULL
    UNION ALL
    SELECT 'Apalaín', 'Genista spartioides', 'flora', 'Arbusto', 'Laderas secas, ramblas y matorral sobre suelos margosos y pedregosos', 'NE', 'Retama de ramas juncales, verdes y erguidas, prácticamente sin hojas, que florece en amarillo a final de verano, cuando casi todo el matorral está en reposo. Es un endemismo del sureste ibérico.', NULL, 'Ramas verdes largas y juncales, sin hojas visibles; Florece a final de verano y en otoño; Porte erguido en escoba, no en cojín', 'Verano y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Genista_spartioides_kz01.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (85 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Genista', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 4915, 5347582, NULL, NULL, NULL
    UNION ALL
    SELECT 'Arenaria', 'Linaria aeruginea', 'flora', 'Hierba', 'Pedregales, gravas y taludes móviles de montaña', 'NE', 'Linaria de tallos tendidos y hojas algo carnosas de un verde azulado, con flores de colores muy variables —del amarillo al pardo violáceo, a veces bicolores— provistas de un espolón. Vive en pedregales sueltos, donde pocas plantas se asientan.', NULL, 'Color de la flor muy variable, a menudo bicolor; Follaje verde azulado y algo carnoso; Sobre gravas y pedregales sueltos', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Linaria_aeruginea.jpg?width=1280', 'This image is created by user Stijn Hantson at Observation.org, a g… (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (82 ocurrencias en 9 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Plantaginaceae', 'Linaria', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 5906, 5415010, NULL, NULL, NULL
    UNION ALL
    SELECT 'Arce', 'Acer monspessulanum', 'flora', 'Árbol', 'Barrancos, umbrías y bosques mixtos sobre suelos frescos y calizos', 'LC', 'Arce pequeño de hojas coriáceas divididas en tres lóbulos redondeados, mucho menores que las de otros arces. En otoño vira a tonos amarillos y rojizos que destacan en las umbrías. Sus frutos son sámaras dobles con las alas casi paralelas.', NULL, 'Hojas de tres lóbulos redondeados, pequeñas y duras; Sámaras dobles con las alas casi juntas y paralelas; Color otoñal amarillo y rojizo en barrancos umbríos', 'Todo el año, con color otoñal marcado', 'https://commons.wikimedia.org/wiki/Special:FilePath/Acer_monspessulanum_fg01.jpg?width=1280', 'Fritz Geller-Grimm (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (67 ocurrencias en 9 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Sapindales', 'Sapindaceae', 'Acer', 'LC (Preocupación menor) (evaluación UICN 2018)', 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo) · ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo)', 'En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 1924, 7262958, NULL, NULL, NULL
    UNION ALL
    SELECT 'Mayos', 'Limodorum abortivum', 'flora', 'Orquídea', 'Pinares y bosques con hojarasca, en media sombra', 'NE', 'Orquídea sin apenas clorofila que emerge del suelo como un tallo violáceo con las hojas reducidas a escamas. Se alimenta a través de hongos conectados a las raíces de los árboles, así que no depende de la luz. Muchos años ni siquiera llega a abrir las flores.', NULL, 'Tallo violáceo entero, sin hojas verdes; Aparece de golpe entre la hojarasca del pinar; Flores grandes de color lila que a veces no llegan a abrirse', 'Primavera y principio de verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Limodorum_abortivum_Mallorca_04.jpg?width=1280', 'Orchi (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (64 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Orchidaceae', 'Limodorum', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 5809, 5312179, NULL, NULL, NULL
    UNION ALL
    SELECT 'Campanica', 'Convolvulus althaeoides', 'flora', 'Hierba', 'Ribazos, cunetas, cultivos y claros de matorral', 'NE', 'Correhuela trepadora de flores rosadas grandes y llamativas, con hojas muy variables: las de abajo casi enteras y las de arriba profundamente divididas y plateadas. Se enreda en la vegetación de ribazos y márgenes.', NULL, 'Flores rosa intenso en embudo, grandes y vistosas; Hojas superiores muy recortadas y de aspecto plateado; Tallos volubles que se enredan en otras plantas', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Convolvulus_althaeoides_1.JPG?width=1280', 'User:Xemenendura (CC BY-SA 2.1 es) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (64 ocurrencias en 8 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Solanales', 'Convolvulaceae', 'Convolvulus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 3692, 2928400, NULL, NULL, NULL
    UNION ALL
    SELECT 'Espantalobos', 'Colutea arborescens', 'flora', 'Arbusto', 'Bordes de bosque, barrancos y matorral sobre suelos frescos', 'NE', 'Leguminosa arbustiva de flores amarillas y hojas compuestas, célebre por sus frutos: vainas infladas como globos de papel que estallan con un chasquido al apretarlas, de donde le viene el nombre de espantalobos.', NULL, 'Vainas infladas y traslúcidas, como globos; Flores amarillas de forma amariposada; Hojas compuestas por varios pares de foliolos redondeados', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Colutea_arborescens01.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (57 ocurrencias en 8 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Colutea', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 3496, 7844167, NULL, NULL, NULL
    UNION ALL
    SELECT 'Geranio de roca', 'Erodium saxatile', 'flora', 'Hierba', 'Fisuras y repisas de roquedos calizos', 'NE', 'Geranio rupícola de rosetas compactas y hojas divididas y algo peludas, con flores rosadas o blanquecinas de venas marcadas. Vive encajado en las grietas de los cantiles, donde encuentra humedad y escapa de los herbívoros.', NULL, 'Rosetas apretadas metidas en la grieta de la roca; Flores rosadas con venas más oscuras; Frutos con pico largo que se enrolla al secarse', 'Primavera', 'https://inaturalist-open-data.s3.amazonaws.com/photos/483580471/original.jpeg', 'Olivier Argagnon (CC BY 4.0) · GBIF/iNaturalist', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (55 ocurrencias en 10 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Geraniales', 'Geraniaceae', 'Erodium', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 32684, 8182781, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cabrilla', 'Cytinus ruber', 'flora', 'Planta parásita', 'Sobre las raíces de jaras y jarillas, en matorral mediterráneo', 'NE', 'Planta parásita sin clorofila que vive dentro de las raíces de las jaras y solo asoma para florecer: un ramillete de flores rosadas y blancas que brota directamente del suelo, al pie de la mata hospedadora. El resto del año es invisible.', NULL, 'Brota directamente del suelo, sin tallo ni hojas verdes; Siempre al pie de una jara o jarilla; Flores rosadas con brácteas carnosas y llamativas', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cytinus_ruber_(flowering_plants).jpg?width=1280', 'Hans Hillewaert (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (54 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cytinaceae', 'Cytinus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 3809, 3941138, NULL, NULL, NULL
    UNION ALL
    SELECT 'Mayos', 'Ophrys lutea', 'flora', 'Orquídea', 'Pastizales, claros de matorral y tomillares sobre suelos calizos', 'NE', 'Orquídea que engaña a los insectos: su labelo imita el cuerpo de una abeja hembra, con un ancho borde amarillo y una mancha central azulada y aterciopelada. Los machos intentan copular con la flor y salen cargados de polen.', NULL, 'Labelo con ancho reborde amarillo brillante; Mancha central azulada y aterciopelada, como un espejo; Flores pocas y espaciadas en un tallo corto', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ophrys_lutea.JPG?width=1280', 'autor no indicado (CC BY-SA 1.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (53 ocurrencias en 9 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Orchidaceae', 'Ophrys', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 6747, 9226313, NULL, NULL, NULL
    UNION ALL
    SELECT 'Aladierno', 'Rhamnus alaternus', 'flora', 'Arbusto', 'Matorral alto, encinares y barrancos sobre suelos pedregosos', 'LC', 'Arbusto perennifolio de hojas alternas, coriáceas y de borde finamente dentado, sin espinas. Sus frutos maduran de rojo a negro y son muy buscados por los pájaros. Se distingue del espino negro por carecer de espinas y tener hojas mayores.', NULL, 'Sin espinas, a diferencia de otros ramnos; Hojas alternas, coriáceas y algo dentadas; Frutos que pasan de rojo a negro al madurar', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rhamnus_alaternus1627.JPG?width=1280', 'tato grasso (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (46 ocurrencias en 8 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Rhamnaceae', 'Rhamnus', 'LC (Preocupación menor) (evaluación UICN 2018)', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 7684, 6371424, NULL, NULL, NULL
    UNION ALL
    SELECT 'Hierba de la cruz', 'Poterium ancistroides', 'flora', 'Hierba', 'Roquedos, pedregales y pastizales pedregosos de montaña', 'NE', 'Pimpinela de base leñosa y hojas divididas en foliolos pequeños y dentados, con cabezuelas globosas de flores verdosas y rojizas que carecen de pétalos. Crece agarrada a la roca y a los pedregales calizos.', NULL, 'Cabezuelas globosas verdosas o rojizas, sin pétalos; Hojas divididas en muchos foliolos dentados; Base leñosa y porte compacto sobre roca', 'Primavera', 'https://inaturalist-open-data.s3.amazonaws.com/photos/517007573/original.jpg', 'FloresdeMurcia.com (CC BY-NC 4.0) · GBIF/iNaturalist', NULL, NULL, 1, NULL, 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (45 ocurrencias en 6 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Rosaceae', 'Poterium', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'UICN España: NT (Casi amenazado) (2010)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 7955, 5364239, NULL, NULL, NULL
    UNION ALL
    SELECT 'Esparto', 'Macrochloa tenacissima', 'flora', 'Gramínea', 'Laderas secas y llanos sobre suelos pobres; forma espartales extensos', 'VU', 'El esparto, nombrado también como Stipa tenacissima, forma matas densas y duraderas que dan nombre a los espartales, uno de los paisajes característicos del sureste ibérico. Sus hojas se enrollan sobre sí mismas en los días secos para perder menos agua y se abren tras la lluvia. Durante siglos se recolectó para hacer cuerdas, esteras y alpargatas.', NULL, 'Matas grandes y compactas de hojas duras enrolladas; Las hojas se abren tras la lluvia y se enrollan al secar; Espigas altas y plateadas a final de primavera', 'Primavera (espigado)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Stipa_tenacissima.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (43 ocurrencias en 8 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Macrochloa', 'VU (Vulnerable) (evaluación UICN 2018)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 27376, 4127897, NULL, NULL, NULL
    UNION ALL
    SELECT 'Madreselva', 'Lonicera splendida', 'flora', 'Arbusto', 'Roquedos, barrancos y matorral sobre suelos calizos', 'NE', 'Madreselva trepadora de hojas opuestas, azuladas y soldadas por la base formando un disco que atraviesa el tallo. Sus flores blanquecinas o rosadas, muy perfumadas, se abren al atardecer para atraer polillas. Es un endemismo del sur peninsular.', NULL, 'Hojas superiores soldadas en un disco atravesado por el tallo; Follaje de tono azulado o glauco; Flores muy perfumadas que abren al anochecer', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lonicera_splendida_2018-05-22_2462.jpg?width=1280', 'Salicyna (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (42 ocurrencias en 9 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Dipsacales', 'Caprifoliaceae', 'Lonicera', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 6048, 5598572, NULL, NULL, NULL
    UNION ALL
    SELECT 'Labiérnago', 'Phillyrea angustifolia', 'flora', 'Arbusto', 'Matorral mediterráneo y laderas secas sobre suelos pedregosos', 'NE', 'Arbusto de hojas opuestas, estrechas y coriáceas, muy parecido a un acebuche pero con las hojas verdes por ambas caras. Sus frutos son pequeñas drupas azuladas o negras que consumen zorzales y currucas.', NULL, 'Hojas opuestas y estrechas, verdes por las dos caras; Sin el reverso plateado del acebuche; Frutos pequeños azulados o negros', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Phyllirea_angustifolia.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (41 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Oleaceae', 'Phillyrea', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 7077, 7325947, NULL, NULL, NULL
    UNION ALL
    SELECT 'Helianthemum viscarium', 'Helianthemum viscarium', 'flora', 'Mata', 'Tomillares y matorral raso sobre margas y suelos yesosos', 'NE', 'Jarilla pequeña y pegajosa, con hojas estrechas y tallos cubiertos de pelos glandulosos que retienen el polvo. Sus flores amarillas duran apenas unas horas y se renuevan cada día. Es un endemismo del sureste ibérico ligado a suelos margosos.', NULL, 'Tallos pegajosos, con polvo y arena adheridos; Flores amarillas efímeras, de un solo día; Sobre margas y yesos, en terreno claro', 'Primavera', 'https://inaturalist-open-data.s3.amazonaws.com/photos/384325778/original.jpg', 'anarkis (CC BY-NC 4.0) · GBIF/iNaturalist', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (40 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Helianthemum', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 5103, 7331463, NULL, NULL, NULL
    UNION ALL
    SELECT 'Rana común', 'Pelophylax perezi', 'fauna', 'Anfibio', 'Charcas, balsas, acequias y tramos remansados con vegetación', 'LC', 'La rana verde ibérica, la más común y adaptable de nuestros anfibios: coloniza desde ramblas y balsas de riego hasta fuentes urbanas. Su canto es un cacareo entrecortado que forma coros al atardecer. Salta al agua al menor movimiento en la orilla.', NULL, 'Línea clara a lo largo del centro del lomo en muchos ejemplares; Canto entrecortado, como una risa o un cacareo; Salta al agua desde la orilla al notar movimiento', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pelophylax_perezi_by-dpc.jpg?width=1280', 'David Perez (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (40 ocurrencias en 6 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Chordata', 'Amphibia', 'Anura', 'Ranidae', 'Pelophylax', 'LC (Preocupación menor) (evaluación UICN 2022)', 'Anexo VI (Ley 42/2007, de 13 de diciembre, del Patrimonio Natural y de la Biodiversidad. BOE 299, de 14 de diciembre de 2007); UICN España: LC (Preocupación menor) (2002)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 11964, 2426658, NULL, NULL, NULL
    UNION ALL
    SELECT 'Epipactis kleinii', 'Epipactis kleinii', 'flora', 'Orquídea', 'Pinares y bosques secos con hojarasca, en media sombra', 'NE', 'Orquídea forestal de tallo delgado y hojas estrechas dispuestas en dos filas, con flores pequeñas de tonos blanquecinos y rosados. Es discreta y se pasa por alto con facilidad entre la hojarasca del pinar.', NULL, 'Hojas estrechas alineadas en dos filas a lo largo del tallo; Flores pequeñas y colgantes, blanquecinas o rosadas; Crece dispersa entre la hojarasca de pinares y bosques secos', 'Primavera y principio de verano', 'https://bs.plantnet.org/image/o/fa3e211eacbd1612f2e8967c671667bdfafb8228', 'janet_phi (CC BY-SA 4.0) · GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (40 ocurrencias en 7 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Orchidaceae', 'Epipactis', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 4341, 5318903, NULL, NULL, NULL
    UNION ALL
    SELECT 'Quejigo', 'Quercus faginea', 'flora', 'Árbol', 'Umbrías y suelos frescos y profundos, en transición al bosque mediterráneo', 'LC', 'Roble mediterráneo de hojas dentadas, más grandes que las de la encina, verdes por el haz y algo blanquecinas por el envés. Es marcescente: las hojas secas quedan colgando del árbol todo el invierno y no caen hasta que brotan las nuevas.', NULL, 'Hojas secas que persisten en la rama todo el invierno; Hoja dentada, mayor y más blanda que la de la encina; Prefiere umbrías y vaguadas con suelo profundo', 'Primavera a otoño (marcescente en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Quercus_faginea_centenario.jpg?width=1280', 'Carlosblh (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (39 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fagales', 'Fagaceae', 'Quercus', 'LC (Preocupación menor) (evaluación UICN 2018)', 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO XII. Especies a las que se refiere la disposición adicional tercera (otras especies forestales importantes para la selvicultura en España) (Real Decreto 289/2003, de 7 de marzo, sobre la comercialización de los materiales forestal…)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 7479, 2881480, NULL, NULL, NULL
    UNION ALL
    SELECT 'Madroño', 'Arbutus unedo', 'flora', 'Arbusto', 'Umbrías, barrancos y matorral alto sobre suelos frescos', 'LC', 'Arbusto o arbolillo de hojas lustrosas y dentadas y corteza rojiza que se desprende en tiras. En otoño coinciden en la misma rama las flores blancas en racimos colgantes y los frutos rojos y granulosos del año anterior.', NULL, 'Flores y frutos a la vez en la misma rama, en otoño; Frutos rojos esféricos de superficie granulosa; Corteza rojiza que se desprende en tiras finas', 'Otoño e invierno (flor y fruto a la vez)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Arbutus_unedo_Corsica.jpg?width=1280', 'jxandreani (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (38 ocurrencias en 6 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Ericales', 'Ericaceae', 'Arbutus', 'LC (Preocupación menor) (evaluación UICN 2017)', 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo) · ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo) · CEEEI: Incluido (Real Decreto 630/2013, de 2 de agosto) · y 1 figura más en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 2284, 2882803, NULL, NULL, NULL
    UNION ALL
    SELECT 'Floreta', 'Coronilla juncea', 'flora', 'Arbusto', 'Matorral seco y laderas soleadas sobre suelos pedregosos', 'NE', 'Leguminosa de tallos verdes, largos y flexibles, casi sin hojas —que caen pronto para ahorrar agua—, rematados en umbelas de flores amarillas. Sus frutos son legumbres articuladas que se rompen en segmentos con una semilla cada uno.', NULL, 'Tallos verdes y juncosos, casi sin hojas; Umbelas de flores amarillas en el extremo; Legumbres articuladas, como collares de cuentas', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Coronilla_juncea.JPG?width=1280', 'Mario Modesto Mata (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (37 ocurrencias en 7 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Coronilla', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 3731, 5348659, NULL, NULL, NULL
    UNION ALL
    SELECT 'Ammoides', 'Ammoides pusilla', 'flora', 'Hierba', 'Pastizales anuales, claros de matorral y suelos removidos', 'LC', 'Umbelífera anual y menuda, con hojas divididas en segmentos filiformes y pequeñas umbelas de flores blancas. Desprende un olor aromático fuerte al estrujarla. Forma parte de las comunidades efímeras que aparecen tras las lluvias de primavera.', NULL, 'Hojas divididas en segmentos como hilos; Umbelas blancas pequeñas y de pocos radios; Olor aromático marcado al estrujar la planta', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ammoides_pusilla_Enfoqueflores_2011-6-11_CampodeCalatrava.jpg?width=1280', 'javier martin (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (37 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Apiales', 'Apiaceae', 'Ammoides', 'LC (Preocupación menor) (evaluación UICN 2015)', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 1834, 6026523, NULL, NULL, NULL
    UNION ALL
    SELECT 'Bocha blanca', 'Lotus dorycnium', 'flora', 'Mata', 'Matorral, ribazos y claros sobre suelos secos y calizos', 'NE', 'Mata baja y grisácea por la pelusa que la cubre, con hojas divididas en foliolos estrechos y ramilletes apretados de florecillas blancas con la quilla oscura. Es muy frecuente en los claros del matorral.', NULL, 'Ramilletes densos de flores blancas muy pequeñas; Quilla de la flor con la punta oscura; Aspecto grisáceo por la pelusa que cubre la planta', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Dorycnium_pentaphyllum_Habitat_2010-6-15_DehesaBoyaldePuertollano.jpg?width=1280', 'Javier martin (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (36 ocurrencias en 8 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Lotus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 4138, 5632022, NULL, NULL, NULL
    UNION ALL
    SELECT 'Athamanta hispanica', 'Athamanta hispanica', 'flora', 'Hierba', 'Fisuras y repisas de roquedos calizos de montaña', 'NE', 'Umbelífera rupícola de hojas muy divididas y cubiertas de pelos, con umbelas de flores blancas sostenidas por tallos finos. Es un endemismo ibérico restringido a cantiles calizos del sureste, donde forma pequeñas poblaciones aisladas.', NULL, 'Hojas muy divididas y con pelos, de aspecto grisáceo; Umbelas blancas pequeñas, en pared rocosa; Crece encajada en fisuras, colgando del cantil', 'Verano', 'https://observation.org/photos/83864093.jpg', 'Fco. Javier López Espino (CC BY-NC-ND 4.0) · observation.org / GBIF', NULL, NULL, 4, '{"categoria":"UICN España: VU (Vulnerable) (2010)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"UICN España: VU (Vulnerable) (2010)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (36 ocurrencias en 8 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Apiales', 'Apiaceae', 'Athamanta', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'UICN España: VU (Vulnerable) (2010)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', 'Pliego de herbario: no existe ninguna fotografía de campo de este taxón con licencia libre. El servidor de origen no permite el enlace directo, así que la imagen se sirve como copia local del repositorio (lo permite su licencia).', 2618, 3633714, NULL, NULL, NULL
    UNION ALL
    SELECT 'Ajo silvestre', 'Allium pallens', 'flora', 'Planta bulbosa', 'Pastizales secos, ribazos y claros de matorral', 'LC', 'Ajo silvestre de umbela laxa y colgante, con flores acampanadas de tonos rosados o pardo claro sobre pedicelos largos y desiguales. Las brácteas que envuelven la inflorescencia acaban en dos puntas largas como cuernos.', NULL, 'Umbela laxa y desmadejada, con flores colgantes; Dos brácteas largas como cuernos bajo la umbela; Olor a ajo al estrujar las hojas', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Laguna_de_San_Juan_20100617_3431.jpg?width=1280', 'Alberto Salguero (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (35 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28. Nombre aceptado en EIDOS; Allium paniculatum es sinónimo.', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Amaryllidaceae', 'Allium', 'LC (Preocupación menor) (evaluación UICN 2011)', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 2029, 2856288, NULL, NULL, NULL
    UNION ALL
    SELECT 'Clavellina', 'Dianthus broteri', 'flora', 'Hierba', 'Pastizales secos, arenales y claros de matorral sobre suelos pobres', 'NE', 'Clavellina silvestre de tallos finos y hojas muy estrechas, con flores rosadas de pétalos profundamente recortados en flecos. El cáliz es un tubo largo y estrecho del que asoman los pétalos. Desprende una fragancia suave, más perceptible al atardecer.', NULL, 'Pétalos rosados recortados en flecos finos; Cáliz en tubo largo y delgado; Hojas muy estrechas, casi como agujas', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Dianthus_broteri.jpg?width=1280', 'Nanosanchez (Public domain) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"UICN España: VU (Vulnerable) (2010)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"UICN España: VU (Vulnerable) (2010)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (35 ocurrencias en 6 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Caryophyllaceae', 'Dianthus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'UICN España: VU (Vulnerable) (2010)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 4072, 7267842, NULL, NULL, NULL
    UNION ALL
    SELECT 'poliol atomillado', 'Teucrium thymifolium', 'flora', 'Mata aromática', 'Roquedos, pedregales y matorral raso sobre calizas de montaña', 'NE', 'Mata pequeña y grisácea de hojas diminutas y enrolladas parecidas a las del tomillo, con flores de un rosa purpúreo. Como todos los teucrios, la flor carece de labio superior, dejando los estambres al descubierto. Es un endemismo del sureste ibérico.', NULL, 'Hojas minúsculas y enrolladas, como de tomillo; Flores rosa púrpura sin labio superior; Sobre roca y pedregal calizo, en matas bajas', 'Primavera y verano', 'https://inaturalist-open-data.s3.amazonaws.com/photos/627242096/original.jpg', 'Finlay F. K. Thorpe (CC BY-NC 4.0) · GBIF/iNaturalist', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (35 ocurrencias en 8 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Teucrium', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 8844, 3892761, NULL, NULL, NULL
    UNION ALL
    SELECT 'Álamo blanco', 'Populus alba', 'flora', 'Árbol', 'Riberas, sotos y suelos con capa freática cercana', 'LC', 'Árbol de ribera con el envés de las hojas cubierto de un fieltro blanco que hace que la copa parezca cambiar de color con el viento. La corteza es clara y con lenticelas romboidales oscuras. Rebrota de raíz con facilidad y forma bosquetes clonales.', NULL, 'Envés de la hoja blanco: la copa «platea» con el viento; Corteza clara con marcas romboidales oscuras; Retoños de raíz alrededor del pie principal', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Populus_alba_01.jpg?width=1280', 'la la means I love you (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (33 ocurrencias en 6 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Malpighiales', 'Salicaceae', 'Populus', 'LC (Preocupación menor) (evaluación UICN 2018)', 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO I. Lista de especies forestales e híbiridos artificiales (Real Decreto 289/2003, de 7 de marzo, sobre la comercialización de los materiales forestal…)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 7290, 3040233, NULL, NULL, NULL
    UNION ALL
    SELECT 'Labiérnago prieto', 'Phillyrea latifolia', 'flora', 'Arbusto', 'Encinares, matorral alto y umbrías sobre suelos pedregosos', 'LC', 'Arbusto o arbolillo de hojas opuestas, coriáceas y de borde dentado, más anchas que las de su pariente de hoja estrecha. Las hojas jóvenes son marcadamente dentadas y las adultas casi enteras, lo que despista con frecuencia.', NULL, 'Hojas opuestas y anchas, dentadas en las ramas jóvenes; Verde oscuro por las dos caras; Frutos pequeños azul negruzcos', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Phillyrea_latifolia.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (32 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Oleaceae', 'Phillyrea', 'LC (Preocupación menor) (evaluación UICN 2017)', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 7079, 7325923, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lirio', 'Iris lutescens', 'flora', 'Planta bulbosa', 'Pastizales pedregosos, ribazos y claros de matorral sobre calizas', 'NE', 'Lirio enano de rizoma superficial y hojas en abanico, con flores grandes que pueden ser amarillas o violetas en la misma población. Los pétalos externos llevan una cresta de pelos que guía a los abejorros hacia el néctar.', NULL, 'Flores grandes sobre un tallo muy corto, casi a ras de suelo; Cresta de pelos en los pétalos externos; Hojas planas dispuestas en abanico', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Iris_lutescens_(flowers).jpg?width=1280', 'Hans Hillewaert (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (30 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Iridaceae', 'Iris', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 5409, 5298190, NULL, NULL, NULL
    UNION ALL
    SELECT 'Salado', 'Ononis fruticosa', 'flora', 'Arbusto', 'Pedregales, taludes y matorral sobre suelos calizos y margosos', 'NE', 'Leguminosa arbustiva de hojas con tres foliolos estrechos y dentados y racimos de flores rosadas con venas más oscuras. Es una planta pionera que fija taludes y pedregales, donde sus raíces profundas aguantan el movimiento del sustrato.', NULL, 'Flores rosadas con venas oscuras bien marcadas; Hojas de tres foliolos estrechos y dentados; Coloniza taludes y pedregales sueltos', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ononis_fruticosa.jpg?width=1280', 'Arrakatanga33 (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (30 ocurrencias en 7 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Ononis', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 6687, 2977293, NULL, NULL, NULL
    UNION ALL
    SELECT 'Klasea flavescens', 'Klasea flavescens', 'flora', 'Hierba', 'Pastizales secos, claros de matorral y taludes sobre suelos margosos', 'NE', 'Compuesta de hojas divididas y algo espinosas, con capítulos grandes de flores amarillas rodeados de brácteas secas y brillantes. A distancia recuerda a un cardo, pero sus hojas pinchan mucho menos.', NULL, 'Capítulos amarillos grandes y solitarios; Brácteas secas y algo brillantes bajo la flor; Hojas divididas, con dientes poco punzantes', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Klasea_flavescens0001_01.jpg?width=1280', 'Philmarin (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (29 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Klasea', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 5535, 3091206, NULL, NULL, NULL
    UNION ALL
    SELECT 'Gayuba', 'Arctostaphylos uva-ursi', 'flora', 'Mata', 'Pinares aclarados, crestas y laderas pedregosas de montaña', 'NE', 'Mata rastrera de hojas pequeñas, coriáceas y brillantes que forma alfombras densas sobre el suelo del pinar. Sus flores son urnas blanco rosadas colgantes y sus frutos, bayas rojas y harinosas. Ayuda a fijar el suelo en laderas pedregosas.', NULL, 'Porte rastrero formando alfombras continuas; Hojas pequeñas, duras y muy brillantes; Flores en urna colgante y frutos rojos harinosos', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Gayuba.jpg?width=1280', 'No machine-readable author provided. Carlosblh assumed (based on co… (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (28 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Ericales', 'Ericaceae', 'Arctostaphylos', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 2292, 2882580, NULL, NULL, NULL
    UNION ALL
    SELECT 'Ortiga muerta', 'Stachys circinata', 'flora', 'Hierba', 'Roquedos, taludes umbríos y pies de cantil', 'NE', 'Labiada de hojas anchas, arrugadas y cubiertas de pelo suave, que crece en repisas y pies de roca umbríos. Sus flores, blanquecinas o rosadas con manchas, se agrupan en verticilos. Recuerda a una ortiga, pero no pica.', NULL, 'Hojas anchas y arrugadas, de tacto aterciopelado; Flores en anillos alrededor del tallo cuadrado; En pies de roca y taludes umbríos', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Stachys_circinata.JPG?width=1280', 'Xemenendura (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (26 ocurrencias en 7 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Stachys', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 8618, 3884228, NULL, NULL, NULL
    UNION ALL
    SELECT 'Olmo común', 'Ulmus minor', 'flora', 'Árbol', 'Sotos, vegas y suelos profundos con humedad freática', 'DD', 'Árbol de hojas asimétricas en la base —un lado baja más que el otro— y borde doblemente aserrado. Florece antes de echar la hoja y fructifica en sámaras redondeadas y membranosas. La grafiosis ha diezmado sus poblaciones adultas.', NULL, 'Base de la hoja claramente asimétrica; Sámaras redondas y papiráceas antes que las hojas; Rebrota de raíz formando setos y orlas', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Blismes_elm_2007.jpg?width=1280', 'Eric Collin. Original uploader was Ptelea at en.wikipedia (GFDL) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (25 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Ulmaceae', 'Ulmus', 'DD (Datos insuficientes) (evaluación UICN 2017)', 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO XII. Especies a las que se refiere la disposición adicional tercera (otras especies forestales importantes para la selvicultura en España) (Real Decreto 289/2003, de 7 de marzo, sobre la comercialización de los materiales forestal…)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 9147, 5361865, NULL, NULL, NULL
    UNION ALL
    SELECT 'Sanjuán blanco', 'Cephalanthera longifolia', 'flora', 'Orquídea', 'Bosques y pinares con sombra y hojarasca, sobre suelos calizos', 'NE', 'Orquídea de porte erguido con hojas largas y estrechas dispuestas en dos filas y flores blancas que apenas llegan a abrirse del todo. Vive en la penumbra del bosque y depende de hongos del suelo para germinar y crecer.', NULL, 'Flores blancas semicerradas, en espiga laxa; Hojas largas y estrechas en dos filas; En sombra de bosque, sobre hojarasca', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cephalanthera_longifolia_300508.jpg?width=1280', 'Bernd Haynold (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (25 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Orchidaceae', 'Cephalanthera', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 3379, 2795869, NULL, NULL, NULL
    UNION ALL
    SELECT 'culantrillo glanduloso', 'Asplenium petrarchae', 'flora', 'Helecho', 'Grietas de roquedos calizos secos y soleados, y muros antiguos', 'NE', 'Helecho pequeño que sobrevive en fisuras de roca caliza expuestas al sol, algo insólito en un grupo que suele buscar la humedad. Sus frondes son cortas, divididas y cubiertas de pelos glandulosos. En sequía se enrolla y parece muerto, y revive con la lluvia.', NULL, 'Frondes pequeñas, divididas y con pelos pegajosos; En grietas de roca seca y soleada, no en umbrías húmedas; Se reseca y enrolla en verano, y rebrota con la lluvia', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Petrarchae.jpg?width=1280', 'Juan Bibiloni (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (24 ocurrencias en 7 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Polypodiopsida', 'Polypodiales', 'Aspleniaceae', 'Asplenium', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 2546, 7310803, NULL, NULL, NULL
    UNION ALL
    SELECT 'Olmo de montaña', 'Ulmus glabra', 'flora', 'Árbol', 'Barrancos húmedos y umbrías frescas de montaña', 'DD', 'Olmo de hojas grandes, ásperas al tacto como papel de lija y con la base muy asimétrica, a menudo con la punta dividida en tres. Prefiere barrancos frescos y umbríos, y no rebrota de raíz como el olmo común.', NULL, 'Hojas grandes y muy ásperas al tacto; Punta de la hoja a menudo dividida en tres lóbulos; En barrancos umbríos y frescos, no en vegas secas', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ulmus_glabra_horizontalis.jpg?width=1280', 'Melburnian (CC BY 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (23 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Ulmaceae', 'Ulmus', 'DD (Datos insuficientes) (evaluación UICN 2017)', 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo) · ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo) · ANEXO XII. Especies a las que se refiere la disposición adicional tercera (otras especies forestales importantes para la selvicultura en España) (Real Decreto 289/2003, de 7 de marzo)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 9144, 5361866, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cerezo rastrero', 'Prunus prostrata', 'flora', 'Arbusto', 'Crestas, pedregales y matorral almohadillado de alta montaña', 'LC', 'Cerezo enano de porte rastrero y ramas retorcidas, adaptado al viento y al frío de las cumbres. Florece en rosa antes de echar la hoja y da drupas rojas pequeñas y ácidas. Rara vez levanta más de un palmo del suelo.', NULL, 'Porte rastrero y retorcido, pegado a la roca; Flores rosadas antes de que salgan las hojas; Frutillos rojos parecidos a cerezas diminutas', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Prunus_prostrata.jpg?width=1280', 'User:Tigerente (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (22 ocurrencias en 6 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Rosaceae', 'Prunus', 'LC (Preocupación menor) (evaluación UICN 2016)', 'Sin figura de protección nacional específica registrada en EIDOS', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 7394, 3021265, NULL, NULL, NULL
    UNION ALL
    SELECT 'Mirto', 'Myrtus communis', 'flora', 'Arbusto', 'Barrancos, umbrías y matorral alto sobre suelos frescos', 'LC', 'Arbusto aromático de hojas opuestas, brillantes y coriáceas que al mirarlas a contraluz muestran puntitos translúcidos: son las glándulas de aceite esencial. Sus flores blancas tienen un penacho de estambres y sus frutos son bayas azul negruzcas.', NULL, 'Puntos translúcidos en la hoja al mirarla a contraluz; Aroma intenso al estrujar una hoja; Flores blancas con muchos estambres, como un pincel', 'Verano (floración) y otoño (fruto)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Starr_080304-3229_Myrtus_communis.jpg?width=1280', 'Forest & Kim Starr (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (22 ocurrencias en 6 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Myrtales', 'Myrtaceae', 'Myrtus', 'LC (Preocupación menor) (evaluación UICN 2018)', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 6498, 3180085, NULL, NULL, NULL
    UNION ALL
    SELECT 'Guillomero', 'Cotoneaster granatensis', 'flora', 'Arbusto', 'Roquedos, pedregales y matorral de montaña, a menudo en umbría', 'NT', 'Arbusto de hojas ovaladas, verdes por el haz y blanquecinas y afieltradas por el envés, con flores blancas o rosadas agrupadas en corimbos. En otoño da frutos rojos que atraen a zorzales y currucas. Es un endemismo del sur y sureste peninsular.', NULL, 'Envés de la hoja blanquecino y afieltrado; Frutos rojos pequeños agrupados, muy visibles en otoño; Porte arbustivo entre rocas, a menudo colgante', 'Primavera (floración) y otoño (fruto)', 'https://observation.org/photos/83833755.jpg', 'Paco (Faluke) (CC BY-NC-ND 4.0) · observation.org / GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (22 ocurrencias en 7 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Rosaceae', 'Cotoneaster', 'NT (Casi amenazado) (evaluación UICN 1998)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 3759, 3025671, NULL, NULL, NULL
    UNION ALL
    SELECT 'Milamores', 'Centranthus lecoqii', 'flora', 'Hierba', 'Roquedos, muros, taludes y pedregales', 'NE', 'Planta de hojas opuestas y algo carnosas, de un verde azulado, con densos ramilletes de flores rosadas o lilas provistas de un espolón fino. Coloniza muros viejos, taludes y pedregales, donde forma manchas muy vistosas.', NULL, 'Ramilletes densos de flores rosadas o lilas; Cada flor con un espolón fino por detrás; Follaje glauco, algo carnoso y azulado', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Centranthus_lecoqii_subsp._lecoqii_4154.JPG?width=1280', 'Vachiclub (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (22 ocurrencias en 8 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Dipsacales', 'Caprifoliaceae', 'Centranthus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 3369, 7298976, NULL, NULL, NULL
    UNION ALL
    SELECT 'Artemisia reptans', 'Artemisia reptans', 'flora', 'Mata', 'Pedregales, gravas y suelos removidos de montaña', 'NE', 'Artemisia de porte rastrero que se extiende por el suelo formando alfombras, con hojas divididas y cubiertas de pelo blanco. Sus capítulos son pequeños y poco vistosos, como en casi todas las artemisias. Desprende un olor amargo característico.', NULL, 'Porte rastrero, extendiéndose por el suelo; Hojas divididas y cubiertas de pelusa blanca; Olor amargo y aromático al frotar', 'Verano y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Artemisia_reptans_Samuel_Correa_Falc%C3%B3n_2022_GC.jpg?width=1280', 'SamuelCorreaFalcón (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"UICN España: VU (Vulnerable) (2010)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"UICN España: VU (Vulnerable) (2010)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (20 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Artemisia', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'UICN España: VU (Vulnerable) (2010)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', 'Foto localizada por búsqueda en Commons (no por el elemento de Wikidata del taxón): conviene confirmar que corresponde a esta especie.', 60, 8623188, NULL, NULL, NULL
    UNION ALL
    SELECT 'Manzanilla bastarda', 'Anacyclus valentinus', 'flora', 'Hierba', 'Cunetas, eriales, ramblas y suelos removidos', 'NE', 'Compuesta anual de hojas muy divididas y capítulos amarillos que suelen carecer de lígulas, por lo que parecen botones sin pétalos. Es una planta pionera muy frecuente en bordes de camino y terrenos alterados.', NULL, 'Capítulos amarillos sin pétalos visibles, como botones; Hojas finamente divididas, de aspecto plumoso; Frecuente en cunetas y suelos removidos', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/A._valentinus-1.JPG?width=1280', 'Philmarin (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 5, '{"categoria":"UICN España: CR (En peligro crítico) (2010)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"UICN España: CR (En peligro crítico) (2010)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (20 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Anacyclus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'UICN España: CR (En peligro crítico) (2010)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 9800, 3148548, NULL, NULL, NULL
    UNION ALL
    SELECT 'Silene mellifera', 'Silene mellifera', 'flora', 'Hierba', 'Roquedos, taludes y claros de matorral sobre suelos calizos', 'NE', 'Silene de flores blancas cuyos pétalos se abren al atardecer y desprenden un perfume dulce e intenso que atrae a polillas nocturnas. El cáliz es un tubo alargado con venas marcadas. De día las flores suelen aparecer mustias y cerradas.', NULL, 'Flores blancas que abren al anochecer y huelen intensamente; Cáliz tubular con venas bien marcadas; De día las flores parecen marchitas', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Silene_mellifera_Enfoque_2012-05-27_Robledillo_SierraMadrona.jpg?width=1280', 'Javier martin (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (20 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Caryophyllaceae', 'Silene', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 8413, 7267618, NULL, NULL, NULL
    UNION ALL
    SELECT 'epipacte blanca', 'Cephalanthera damasonium', 'flora', 'Orquídea', 'Bosques umbríos con hojarasca sobre suelos calizos', 'NE', 'Orquídea de bosque con hojas anchas y ovaladas y flores de un blanco cremoso que casi nunca llegan a abrirse por completo. Se autopoliniza dentro de la flor cerrada, lo que la hace independiente de los insectos.', NULL, 'Flores color marfil que apenas se entreabren; Hojas anchas y ovaladas, no estrechas; En bosque umbrío, sobre hojarasca', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cephalanthera_damasonium_050606.jpg?width=1280', 'Bernd Haynold (CC BY 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (20 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Orchidaceae', 'Cephalanthera', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 3378, 2795952, NULL, NULL, NULL
    UNION ALL
    SELECT 'Algarrobo', 'Ceratonia siliqua', 'flora', 'Árbol', 'Laderas cálidas, antiguos cultivos y matorral del piso termomediterráneo', 'LC', 'Árbol perennifolio de copa densa y hojas compuestas con foliolos redondeados y lustrosos. Florece en otoño directamente sobre el tronco y las ramas viejas. Sus vainas pardas y dulces, las algarrobas, se han usado durante siglos como pienso y alimento.', NULL, 'Hojas compuestas de foliolos redondos y brillantes; Flores nacidas directamente del tronco y las ramas gruesas; Vainas pardas y aplanadas colgando del árbol', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ceratonia_siliqua_Keciboynuzu_1370984_Nevit.jpg?width=1280', 'Nevit Dilmen (talk) (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (19 ocurrencias en 8 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Ceratonia', 'LC (Preocupación menor) (evaluación UICN 2017)', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 3422, 5356354, NULL, NULL, NULL
    UNION ALL
    SELECT 'Erodium celtibericum', 'Erodium celtibericum', 'flora', 'Hierba', 'Pedregales calizos y crestas de montaña', 'NE', 'Geranio de montaña que forma rosetas compactas de hojas plateadas y muy divididas, con flores rosadas de venas marcadas. Es un endemismo ibérico ligado a pedregales calizos de altura, con poblaciones pequeñas y aisladas.', NULL, 'Rosetas densas de hojas plateadas y muy divididas; Flores rosadas con venas más oscuras; En pedregales de altura, sobre caliza', 'Primavera y verano', 'https://inaturalist-open-data.s3.amazonaws.com/photos/205785187/original.jpg', 'Denys Vynokurov (CC BY 4.0) · GBIF/iNaturalist', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (19 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Geraniales', 'Geraniaceae', 'Erodium', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 80465, 7828997, NULL, NULL, NULL
    UNION ALL
    SELECT 'Mostajo', 'Aria edulis', 'flora', 'Árbol', 'Umbrías y barrancos frescos de montaña, en bosque mixto', 'LC', 'Arbolillo de hojas anchas, dentadas y cubiertas por el envés de un fieltro blanco que las hace destacar cuando sopla el viento. Da corimbos de flores blancas en primavera y frutos rojos y harinosos en otoño, buscados por zorzales y mirlos.', NULL, 'Envés de la hoja blanco y afieltrado; Corimbos de flores blancas en primavera; Frutos rojos harinosos en otoño', 'Primavera (flor) y otoño (fruto y color)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Weilburg_-_Tiergarten_-_Mehlbeere.jpg?width=1280', 'Oliver Abels (SBT) (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (18 ocurrencias en 8 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Rosaceae', 'Aria', 'LC (Preocupación menor) (evaluación UICN 2017)', 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo) · ANEXO XII. Especies a las que se refiere la disposición adicional tercera (otras especies forestales importantes para la selvicultura en España) (Real Decreto 289/2003, de 7 de marzo)', 'En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 8557, 8411755, NULL, NULL, NULL
    UNION ALL
    SELECT 'Tablero de damas', 'Fritillaria lusitanica', 'flora', 'Planta bulbosa', 'Pastizales, claros de matorral y pedregales de montaña', 'NE', 'Bulbosa de tallo fino y hojas estrechas que cuelga una o dos flores en forma de campana, con un jaspeado pardo y verdoso que recuerda a un tablero de ajedrez. Pasa desapercibida entre la hierba pese a su forma llamativa.', NULL, 'Flor colgante en campana con dibujo ajedrezado; Tallo fino con pocas hojas estrechas; Colores apagados que la camuflan en el pastizal', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fritillaria_lusitanica_2_2601.jpg?width=1280', 'Balles2601 (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (17 ocurrencias en 6 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Liliopsida', 'Liliales', 'Liliaceae', 'Fritillaria', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 4633, 5300414, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cabra montés', 'Capra pyrenaica', 'fauna', 'Mamífero ungulado', 'Roquedos, canchales y laderas escarpadas con matorral', 'NE', 'Bóvido de montaña perfectamente adaptado a la roca: pezuñas con borde duro y almohadilla blanda que agarra en pendientes imposibles. Los machos lucen cuernos grandes, curvados hacia atrás y con abultamientos; las hembras los tienen cortos y rectos.', NULL, 'Machos con cuernos grandes curvados hacia atrás; Se mueve por cortados donde nada más puede subir; Excrementos en montoncitos de bolitas cilíndricas', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Capra_pyrenaica_in_Sierra_de_Guadarrama.jpg?width=1280', 'Thomas Holbach (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (16 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Chordata', 'Mammalia', 'Artiodactyla', 'Bovidae', 'Capra', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'UICN España: EN (En peligro) (1992)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 24419, 2441054, NULL, NULL, NULL
    UNION ALL
    SELECT 'Tomillo', 'Thymus zygis', 'flora', 'Mata aromática', 'Tomillares, pastizales secos y claros de matorral sobre suelos pobres', 'NE', 'Tomillo de hojas estrechas y con pelos largos en la base, que forma matas bajas y ramificadas. Es la especie de la que se extrae buena parte del tomillo de uso culinario y de la que se destila aceite esencial rico en timol.', NULL, 'Hojas estrechas con pelos largos y blancos en la base; Espigas de flores blancas o rosadas al final de las ramas; Aroma potente, el clásico del tomillo de cocina', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Thymus_zygis_1.JPG?width=1280', 'Ximenex (CC BY-SA 2.1 es) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (16 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Thymus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 8956, 7793938, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cincoenrama', 'Potentilla caulescens', 'flora', 'Hierba', 'Fisuras y repisas de roquedos calizos, sobre todo en umbría', 'NE', 'Planta rupícola de hojas divididas en cinco foliolos dentados y flores blancas de cinco pétalos algo separados entre sí. Crece colgando de las grietas de los cantiles calizos, formando matas laxas.', NULL, 'Hojas divididas en cinco foliolos dentados; Flores blancas con los pétalos algo separados; Cuelga de fisuras en pared caliza', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Potentilla_caulescens.jpg?width=1280', 'User:Tigerente (CC BY 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (16 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Rosaceae', 'Potentilla', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 7331, 5367397, NULL, NULL, NULL
    UNION ALL
    SELECT 'Serbal común', 'Cormus domestica', 'flora', 'Árbol', 'Umbrías, barrancos y antiguos cultivos de montaña media', 'LC', 'Árbol de hojas compuestas por muchos foliolos dentados, parecido al serbal de cazadores pero con frutos mayores, en forma de pera o manzana diminuta, que solo se vuelven comestibles cuando se pasan y ablandan.', NULL, 'Hoja compuesta de muchos foliolos alargados y dentados; Frutos con forma de perita o manzanita; Corteza que se agrieta en placas rectangulares con la edad', 'Primavera (flor) y otoño (fruto)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sorbus_domestica_FruitsLeaves_BotGardBln0906a.JPG?width=1280', 'BotBln (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (16 ocurrencias en 8 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Rosales', 'Rosaceae', 'Cormus', 'LC (Preocupación menor) (evaluación UICN 2018)', 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', 'Foto localizada por búsqueda en Commons (no por el elemento de Wikidata del taxón): conviene confirmar que corresponde a esta especie.', 8560, 3013215, NULL, NULL, NULL
    UNION ALL
    SELECT 'Nogal', 'Juglans regia', 'flora', 'Árbol', 'Vegas, barrancos y suelos profundos y frescos; a menudo plantado', 'LC', 'Árbol de hoja caduca con hojas compuestas de foliolos grandes y aromáticos y corteza gris que se agrieta con la edad. Sus raíces liberan sustancias que inhiben el crecimiento de otras plantas, por lo que bajo su copa suele haber poco sotobosque.', NULL, 'Hojas compuestas de olor fuerte al estrujarlas; Nueces envueltas en una cáscara verde carnosa; Poca vegetación bajo su copa', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/20110802Walnussbaum_Plankstadt2.jpg?width=1280', 'AnRo0002 (CC0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (15 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Fagales', 'Juglandaceae', 'Juglans', 'LC (Preocupación menor) (evaluación UICN 2017)', 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO XII. Especies a las que se refiere la disposición adicional tercera (otras especies forestales importantes para la selvicultura en España) (Real Decreto 289/2003, de 7 de marzo, sobre la comercialización de los materiales forestal…)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 5457, 3054368, NULL, NULL, NULL
    UNION ALL
    SELECT 'Fresno de flor', 'Fraxinus ornus', 'flora', 'Árbol', 'Umbrías, barrancos y bosques mixtos sobre suelos frescos', 'LC', 'Fresno que, a diferencia de sus parientes, tiene flores blancas y vistosas con pétalos, agrupadas en panículas fragantes que aparecen con las hojas. De su corteza se obtiene el maná, una savia azucarada que se recolectaba tradicionalmente.', NULL, 'Panículas de flores blancas perfumadas, con pétalos; Hojas compuestas opuestas, de foliolos dentados; Yemas grises o pardas, no negras como en otros fresnos', 'Primavera (floración) a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fraxinus_ornus_JPG2.jpg?width=1280', 'Jean-Pol GRANDMONT (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (15 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Oleaceae', 'Fraxinus', 'LC (Preocupación menor) (evaluación UICN 2017)', 'ANEXO I. 1) Lista de especies forestales para la aprobación de unidades de conservación genética in situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…); ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 4628, 3172347, NULL, NULL, NULL
    UNION ALL
    SELECT 'Jarilla', 'Helianthemum violaceum', 'flora', 'Mata', 'Tomillares y matorral raso sobre suelos calizos y margosos secos', 'NE', 'Jarilla pequeña de hojas estrechas y grisáceas con el borde enrollado, que se cubre en primavera de flores amarillas efímeras. Como en todas las jarillas, los pétalos apenas duran una mañana y se renuevan cada día.', NULL, 'Hojas estrechas con el borde enrollado hacia abajo; Flores amarillas que duran solo unas horas; Mata baja y grisácea del tomillar', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Helianthemum_violaceum_habitus_SierraMadrona.jpg?width=1280', 'Javier martin (Public domain) · Wikimedia Commons', NULL, NULL, 1, NULL, 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (15 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Helianthemum', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'UICN España: EN (En peligro) (2010)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 5102, 8148601, NULL, NULL, NULL
    UNION ALL
    SELECT 'Jara cervuna', 'Cistus populifolius', 'flora', 'Mata', 'Jarales y claros de bosque sobre suelos silíceos o descarbonatados', 'NE', 'Jara de hojas anchas y acorazonadas con peciolo, parecidas a las de un chopo, lo que la hace inconfundible entre las jaras ibéricas. Sus flores son blancas, grandes y con el centro amarillo, y salen agrupadas en el extremo de las ramas.', NULL, 'Hojas anchas y acorazonadas, con peciolo largo; Flores blancas grandes con el centro amarillo; Sépalos externos grandes y muy visibles en el capullo', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cistus_populifolius.jpg?width=1280', 'Taken by Carsten Niehaus (user:Lumbar). (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (15 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Cistus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 3625, 7331314, NULL, NULL, NULL
    UNION ALL
    SELECT 'Erica erigena', 'Erica erigena', 'flora', 'Arbusto', 'Suelos húmedos, bordes de curso de agua y zonas de rezume', 'NE', 'Brezo de hojas diminutas en verticilos y flores rosadas en forma de campanilla que se abren en pleno invierno. A diferencia de la mayoría de brezos, necesita humedad constante en el suelo, lo que restringe mucho su presencia.', NULL, 'Flores rosadas acampanadas, en invierno; Hojas minúsculas dispuestas en anillos; Siempre en suelos con humedad permanente', 'Invierno y primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Erica_erigena_2c.JPG?width=1280', 'Consultaplantas (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF (15 ocurrencias en 6 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Ericales', 'Ericaceae', 'Erica', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'En Peligro de Extinción (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silves…)', NULL, 4368, 7327590, NULL, NULL, NULL
    UNION ALL
    SELECT 'Neotinea maculata', 'Neotinea maculata', 'flora', 'Orquídea', 'Pastizales, claros de matorral y pinares sobre suelos calizos', 'NE', 'Orquídea discreta y pequeña, con una espiga densa de flores blanquecinas o rosadas que apenas se abren. Sus hojas basales llevan a menudo un moteado pardo violáceo que le da el nombre. Pasa desapercibida salvo que se busque a propósito.', NULL, 'Espiga apretada de flores muy pequeñas y semicerradas; Hojas basales con manchas pardas o violáceas; Planta menuda, de pocos centímetros', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Neotinea_maculata_(Sardinia).jpg?width=1280', '(Hans Hillewaert) (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (15 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Orchidaceae', 'Neotinea', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 6506, 2812458, NULL, NULL, NULL
    UNION ALL
    SELECT 'Hipérico de fuente', 'Hypericum caprifolium', 'flora', 'Mata', 'Fuentes, rezumes, acequias y bordes de curso de agua', 'NE', 'Hipérico de tallos erguidos con hojas opuestas y soldadas por la base, que rodean el tallo. Vive ligado a puntos con agua permanente, así que su presencia señala fuentes y rezumaderos. Sus flores amarillas tienen los estambres agrupados en haces.', NULL, 'Hojas opuestas soldadas alrededor del tallo; Flores amarillas con muchos estambres en manojos; Siempre junto a fuentes, acequias o rezumes', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hypericum_caprifolium_(NHS).jpg?width=1280', 'The Trustees of the National History Museum in London (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (15 ocurrencias en 5 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Magnoliopsida', 'Malpighiales', 'Hypericaceae', 'Hypericum', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 5174, 3714363, NULL, NULL, NULL
    UNION ALL
    SELECT 'Heleborina rojo oscuro', 'Epipactis atrorubens', 'flora', 'Orquídea', 'Pedregales, claros de bosque y taludes calizos de montaña', 'NE', 'Orquídea de flores de un rojo vinoso oscuro que desprenden aroma a vainilla y atraen a avispas. Crece en pedregales y claros calizos, a menudo en pequeños grupos. Es una de las orquídeas de floración más tardía.', NULL, 'Flores de rojo vinoso oscuro, muy características; Aroma dulce a vainilla al acercarse; En pedregales y taludes calizos, en verano', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Epipactis_atrorubens_flowers.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF (15 ocurrencias en 6 hábitats del parque, point-in-polygon local, https://api.gbif.org), consultado 2026-07-28; EIDOS (IEPNB, MITECO) para taxonomía y estado de conservación, consultado 2026-07-28.', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Orchidaceae', 'Epipactis', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 4335, 5318958, NULL, NULL, NULL
    UNION ALL
    SELECT 'Azor común', 'Accipiter gentilis', 'fauna', 'Ave rapaz', 'Bosques maduros y masas forestales densas con claros', 'LC', 'Rapaz forestal de alas cortas y anchas y cola larga, diseñada para perseguir presas entre los árboles a gran velocidad. Es esquiva y se ve casi siempre de refilón. La hembra llega a ser un tercio mayor que el macho, una diferencia poco habitual entre las aves.', NULL, 'Ceja blanca marcada sobre el ojo, como un antifaz al revés; Vuelo de varios aleteos rápidos seguidos de un planeo corto; Pecho finamente rayado en horizontal en los adultos', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Northern_Goshawk_ad_M2.jpg?width=1280', 'Norbert Kenntner, Berlin (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List) para la presencia en la ZEPA/ZEC ES0000173', 'Chordata', 'Aves', NULL, NULL, 'Accipiter', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000)', 'Ave de la ZEPA ES0000261 (Almenara, Moreras y Cabo Cope)', NULL, 11351, 2480589, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Águila real', 'Aquila chrysaetos', 'fauna', 'Ave rapaz', 'Montañas y sierras con cortados rocosos y amplias zonas abiertas de caza', 'LC', 'La mayor de las águilas ibéricas, con casi dos metros y medio de envergadura y una nuca dorada que le da nombre. Cría en repisas de cantiles y usa territorios enormes, que una pareja defiende durante años. Planea con las alas en una «V» muy suave y bate poco, lo que la distingue de las rapaces menores.', NULL, 'Nuca y cogote de tono dorado, visibles a buena luz; Planea con las alas en «V» muy abierta y bate poco; Tamaño enorme: dobla al ratonero en el mismo cielo', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Maakotka_(Aquila_chrysaetos)_by_Jarkko_J%C3%A4rvinen.jpg?width=1280', 'Jarkko Järvinen (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia (Ley 7/1995): De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List) para la presencia en la ZEPA/ZEC ES0000173; IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Aves', NULL, NULL, 'Aquila', 'LC (Preocupación menor)', 'LESRPE (RD 139/2011); Directiva Aves 2009/147/CE; Ley 42/2007, Anexo IV', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia (Ley 7/1995): De interés especial', NULL, 10888, 2480506, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Águila perdicera', 'Aquila fasciata', 'fauna', 'Ave rapaz', 'Sierras con cortados rocosos y amplias zonas abiertas de matorral y cultivo para cazar', 'Amenazada', 'Águila mediana de alas largas y cola larga, con el vientre blanco finamente rayado y una mancha blanca en la espalda que se ve bien en vuelo. Caza a gran velocidad y a poca altura, sorprendiendo a perdices, conejos y palomas. Las parejas ocupan el mismo cortado durante años.', NULL, 'Mancha blanca en el centro de la espalda, visible desde arriba; Vientre claro y muy rayado, con una banda oscura en el borde del ala; Vuelo bajo y rápido cuando caza, no en círculos altos', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aguila_perdicera.jpg?width=1280', 'Paco Gómez from Castellón, Spain (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"Catálogo Español de Especies Amenazadas: Vulnerable","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: En peligro de extinción (población reproductora muy reducida)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'Libro Rojo de las Aves de España, SEO/BirdLife 2004; Ley 7/1995, de 21 de abril, de la Fauna Silvestre de la Región de Murcia (Anexo I); IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Aves', 'Accipitriformes', 'Accipitridae', 'Aquila', 'LC (población global amplia en Asia y África pese al declive europeo)', 'Catálogo Español de Especies Amenazadas: Vulnerable; Libro Rojo de las Aves de España (SEO/BirdLife, 2004/2021); Directiva Aves 2009/147/CE, Anexo I', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: En peligro de extinción (población reproductora muy reducida)', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 16302, 5844449, 'ES0000173', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Búho real', 'Bubo bubo', 'fauna', 'Ave rapaz nocturna', 'Cortados rocosos, barrancos y laderas con matorral y zonas abiertas de caza', 'Protección especial', 'El mayor búho de Europa, con casi dos metros de envergadura, penachos de plumas erguidos sobre la cabeza y ojos de un naranja encendido. Caza conejos, ratas e incluso otras rapaces. Su canto es un «bu-bo» profundo que se propaga kilómetros por los barrancos en las noches de invierno.', NULL, 'Penachos de plumas erguidos a los lados de la cabeza; Ojos naranjas muy intensos; Canto grave y profundo en las noches de invierno', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bubo_bubo_sibiricus_-_01.JPG?width=1280', 'Carlos Delgado (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Aves', 'Strigiformes', 'Strigidae', 'Bubo', 'LC', 'LESRPE; Directiva Aves 2009/147/CE, Anexo I; Reglamento CITES (CE) 338/97, Anexo A', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 10917, 5959092, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Alcaraván', 'Burhinus oedicnemus', 'fauna', 'Ave esteparia', 'Llanos pedregosos, cultivos de secano, ramblas y eriales con poca cobertura', 'Interés especial', 'Ave de aspecto extraño y ojos amarillos enormes, adaptados a la actividad nocturna. De día permanece agachada e inmóvil, confiada en su plumaje críptico, y solo al anochecer se activa y delata con un reclamo silbado y melancólico que recuerda al del zarapito.', NULL, 'Ojos amarillos desproporcionadamente grandes; Dos barras blancas y negras en el ala plegada; Reclamo silbado y triste al anochecer', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Burhinus_oedicnemus_insularum_Lanzarote_1.jpg?width=1280', 'Frank Vassen from Brussels, Belgium (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Aves', 'Charadriiformes', 'Burhinidae', 'Burhinus', 'LC', 'LESRPE; Directiva Aves 2009/147/CE, Anexo I', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 11887, 2482100, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Chotacabras cuellirrojo', 'Caprimulgus ruficollis', 'fauna', 'Ave', 'Matorral abierto, pinares aclarados, ramblas y caminos térreos', 'NT', 'Ave crepuscular de plumaje jaspeado que imita la hojarasca, tan mimético que de día resulta casi imposible verla posada en el suelo. Caza polillas en vuelo con la boca muy abierta. Su canto nocturno es un «cu-toc, cu-toc» repetido de forma monótona durante minutos.', NULL, 'Collar rojizo en la nuca, más marcado que en su pariente europeo; Se levanta del camino al anochecer y vuelve a posarse unos metros más allá; Canto nocturno monótono, como un motor lejano', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Caprimulgus_ruficollis_-Portugal-8.jpg?width=1280', 'Olivença (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List) para la presencia en la ZEPA/ZEC ES0000173', 'Chordata', 'Aves', NULL, NULL, 'Caprimulgus', 'NT (Casi amenazado)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'Ave de la ZEPA ES0000261 (Almenara, Moreras y Cabo Cope)', NULL, 12122, 9411857, 'ES0000173', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Culebrera europea', 'Circaetus gallicus', 'fauna', 'Ave rapaz', 'Sierras y llanos con matorral, ramblas y bosque abierto', 'LC', 'Águila grande y muy pálida por debajo, especializada en comer culebras y lagartos. Se ciñe en el aire durante largos ratos, con las patas colgando, escrutando el suelo antes de dejarse caer. La cabeza, ancha y con ojos amarillos muy frontales, le da un aire de lechuza.', NULL, 'Vientre y alas casi blancos vistos desde abajo; Se mantiene cerniéndose, algo raro en un águila tan grande; Cabeza ancha y ojos amarillos, aspecto de búho', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aguila_culebrera_(Circaetus_gallicus).jpg?width=1280', 'Paco Gómez (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia (Ley 7/1995): De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List) para la presencia en la ZEPA/ZEC ES0000173; IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Aves', NULL, NULL, 'Circaetus', 'LC (Preocupación menor)', 'LESRPE (RD 139/2011); Directiva Aves 2009/147/CE; Ley 42/2007, Anexo IV', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia (Ley 7/1995): De interés especial', NULL, 11336, 2480666, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Carraca europea', 'Coracias garrulus', 'fauna', 'Ave', 'Campos abiertos con arbolado disperso, ribazos y construcciones con huecos', 'LC', 'Del tamaño de una paloma y de un azul turquesa intenso que sorprende al levantar el vuelo. Caza al acecho desde cables y postes, dejándose caer sobre saltamontes y escarabajos. Cría en huecos de árboles viejos y de edificios, de ahí que dependa de que queden árboles añosos y ruinas en el campo.', NULL, 'Azul turquesa que solo se aprecia bien cuando vuela; Espalda de color canela que contrasta con el azul; Posada quieta en cables, oteando el suelo', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/European_roller.jpg?width=1280', 'Christian Svane (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia (Ley 7/1995): De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List) para la presencia en la ZEPA/ZEC ES0000173; IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Aves', NULL, NULL, 'Coracias', 'LC (Preocupación menor)', 'LESRPE (RD 139/2011); Directiva Aves 2009/147/CE; Ley 42/2007, Anexo IV', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia (Ley 7/1995): De interés especial', NULL, 11339, 2475365, 'ES0000173', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Halcón peregrino', 'Falco peregrinus', 'fauna', 'Ave rapaz', 'Cortados y áreas abiertas', 'Protección especial', 'Halcón robusto de alas puntiagudas y cola corta, capaz de superar los 300 km/h en el picado con que abate a otras aves en pleno vuelo. Se reconoce por la ancha bigotera negra que baja desde el ojo sobre un pecho claro y barrado.', NULL, 'Bigotera negra ancha bajo el ojo, como un casco; Silueta de ancla: alas puntiagudas y cola corta; Pecho claro con barrado fino en horizontal', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Falco_peregrinus_-_01.jpg?width=1280', 'Carlos Delgado (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Aves', 'Falconiformes', 'Falconidae', 'Falco', 'LC', 'LESRPE; Directiva Aves 2009/147/CE, Anexo I; Reglamento CITES (CE) 338/97, Anexo A', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 11963, 2481047, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Cernícalo vulgar', 'Falco tinnunculus', 'fauna', 'Ave rapaz', 'Campos abiertos, matorral, cortados y también ciudades', 'LC', 'El halcón más común y fácil de ver, gracias a su costumbre de cernirse: se queda suspendido en el aire batiendo las alas con la cabeza inmóvil, buscando ratones y lagartijas. El macho tiene la cabeza gris y el dorso rojizo con puntos negros; la hembra es más parda y barrada.', NULL, 'Se queda «clavado» en el aire cerniéndose; Dorso rojizo salpicado de puntos negros; Cola larga con una banda negra ancha en la punta', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Common_kestrel_falco_tinnunculus.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List) para la presencia en la ZEPA/ZEC ES0000173', 'Chordata', 'Aves', NULL, NULL, 'Falco', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000)', 'Ave de la ZEPA ES0000261 (Almenara, Moreras y Cabo Cope)', NULL, 12321, 9616058, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Cogujada común', 'Galerida cristata', 'fauna', 'Ave', 'Cultivos, caminos, eriales y bordes de poblado con suelo desnudo', 'Interés especial', 'Alondra parda de cresta alta y puntiaguda, muy ligada a caminos, cunetas y descampados junto a los pueblos. Camina en vez de saltar y, al volar, deja ver el forro rojizo de las alas y la cola con los bordes canela.', NULL, 'Cresta larga y puntiaguda, casi siempre erguida; Forro de las alas rojizo, visible al levantar el vuelo; Camina por el suelo en vez de saltar', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Crested_Lark_-_Qatar.jpg?width=1280', 'Ashraf Kotb (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Aves', 'Passeriformes', 'Alaudidae', 'Galerida', 'LC', 'LESRPE (RD 139/2011); Directiva Aves 2009/147/CE', 'No catalogada regionalmente', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 11102, 2490669, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Cogujada montesina', 'Galerida theklae', 'fauna', 'Ave', 'Matorral bajo, laderas pedregosas y eriales con vegetación rala', 'Interés especial', 'Cogujada de cresta puntiaguda, muy parecida a la común pero de pico más corto y grueso y con el pecho más nítidamente rayado. Prefiere el matorral y las laderas pedregosas, mientras que la común busca cultivos, caminos y bordes de pueblo.', NULL, 'Cresta alta y afilada, casi triangular; Pico más corto y romo que el de la cogujada común; Rayado del pecho bien definido, no difuminado', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Galerida_theklae_Madrid.jpg?width=1280', 'Adrian198cm (Public domain) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Aves', 'Passeriformes', 'Alaudidae', 'Galerida', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial', 'El PORN cita la presencia de la especie en el parque sin detallar su categoría exacta de protección regional; pendiente de confirmar con el Catálogo Regional vigente. La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 12316, 9330514, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Águila calzada', 'Hieraaetus pennatus', 'fauna', 'Ave rapaz', 'Bosques y sierras con arbolado, cazando sobre zonas abiertas cercanas', 'LC', 'Águila pequeña, del tamaño de un ratonero, con dos formas de plumaje muy distintas: una clara con el vientre blanco y otra oscura y uniforme. Nidifica en árboles dentro del bosque y caza en campo abierto lanzándose desde altura. Se identifica en vuelo por las «luces de posición»: dos manchas blancas en el arranque de las alas.', NULL, 'Dos manchas blancas donde el ala se une al cuerpo; Existen ejemplares claros y oscuros de la misma especie; Cola larga y recta, sin la muesca del milano', 'Primavera y verano (estival); algunos ejemplares invernan', 'https://commons.wikimedia.org/wiki/Special:FilePath/Booted_eagle%2C_Hieraaetus_pennatus%2C_at_Kgalagadi_Transfrontier_Pa_(32334023348).jpg?width=1280', 'Derek Keats from Johannesburg, South Africa (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List) para la presencia en la ZEPA/ZEC ES0000173', 'Chordata', 'Aves', NULL, NULL, 'Hieraaetus', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'Ave de la ZEPA ES0000261 (Almenara, Moreras y Cabo Cope)', NULL, 11959, 2480685, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Torcecuello euroasiático', 'Jynx torquilla', 'fauna', 'Ave', 'Bosques abiertos, sotos, huertos y arboledas con madera muerta', 'LC', 'Pariente de los pájaros carpinteros que ni pica la madera ni trepa por los troncos: se posa de través en las ramas y come hormigas del suelo con una lengua larguísima. Su plumaje jaspeado en grises y pardos imita la corteza. Si se le molesta en el nido, retuerce el cuello como una culebra, de ahí su nombre.', NULL, 'Plumaje veteado como corteza, difícil de ver quieto; Se posa a lo largo de la rama, no agarrado al tronco; Franja oscura desde la nuca hasta la mitad de la espalda', 'Paso migratorio e invernada', 'https://commons.wikimedia.org/wiki/Special:FilePath/Jinxtorquilla.jpg?width=1280', 'User:Aelwyn (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List) para la presencia en la ZEPA/ZEC ES0000173', 'Chordata', 'Aves', NULL, NULL, 'Jynx', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'Ave de la ZEPA ES0000261 (Almenara, Moreras y Cabo Cope)', NULL, 12326, 8012314, 'ES0000173', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Abejaruco europeo', 'Merops apiaster', 'fauna', 'Ave', 'Matorral termomediterráneo semiárido', 'Interés especial', 'Ave colorida y gregaria que caza abejas y libélulas en vuelo sobre espacios abiertos y cría en galerías excavadas en taludes terrosos.', NULL, 'Colorido inconfundible; Reclamo ''prruip'' en vuelo; Cría en taludes de rambla', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%9Eahl%C3%BBr-33.jpg?width=1280', 'Dûrzan cîrano (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Atlas y Manual de los Hábitats de España (MITECO) — especie característica del HIC 5330; Inventario Español EIDOS (IEPNB, taxonid 10738); GBIF (speciesKey 2475443); Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE, RD 139/2011). Directiva Aves 2009/147/CE.', 'Chordata', 'Aves', 'Coraciiformes', 'Meropidae', 'Merops', 'LC', 'LESRPE (RD 139/2011)', 'Fauna protegida; estival que cría en taludes de rambla', NULL, 10738, 2475443, 'ES0000173', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Papamoscas gris', 'Muscicapa striata', 'fauna', 'Ave', 'Arbolado abierto, bordes de bosque, huertos y jardines con perchas altas', 'LC', 'Pájaro discreto de color pardo grisáceo, sin marcas llamativas, que se reconoce mejor por su conducta que por su aspecto: se posa muy erguido en una rama descubierta, sale disparado a cazar un insecto en el aire y vuelve exactamente a la misma percha. Repite la maniobra decenas de veces.', NULL, 'Vuelve siempre a la misma rama tras cada vuelo de caza; Postura muy vertical, con las alas caídas; Frente y pecho con un rayado fino y difuso', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/SpottedFlycatcheronfence.jpg?width=1280', 'Andrew Easton (Attribution) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List) para la presencia en la ZEPA/ZEC ES0000173', 'Chordata', 'Aves', NULL, NULL, 'Muscicapa', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'Ave de la ZEPA ES0000261 (Almenara, Moreras y Cabo Cope)', NULL, 12250, 2492576, 'ES0000173', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Collalba rubia', 'Oenanthe hispanica', 'fauna', 'Ave', 'Laderas secas y pedregosas con matorral bajo y suelo desnudo', 'LC', 'Collalba pequeña y contrastada: el macho es color arena claro con las alas negras y un antifaz o una garganta negros según la variedad. Como todas las collalbas, enseña al volar una cola blanca con una «T» negra invertida. Caza insectos lanzándose al suelo desde una piedra o una mata.', NULL, 'Cola blanca con una «T» negra al abrirse; Alas negras que resaltan sobre el cuerpo color arena; Se posa erguida en piedras y matas, muy visible', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Black-eared_Wheatear%2C_Punta_del_Sabinar%2C_Spain.jpg?width=1280', 'Vince Smith from London, United Kingdom (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List) para la presencia en la ZEPA/ZEC ES0000173', 'Chordata', 'Aves', NULL, NULL, 'Oenanthe', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'Ave de la ZEPA ES0000261 (Almenara, Moreras y Cabo Cope)', NULL, 11453, 5231235, 'ES0000173', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Collalba negra', 'Oenanthe leucura', 'fauna', 'Ave', 'Matorral litoral, laderas secas y roquedos', 'Interés especial', 'La mayor de las collalbas, enteramente negra salvo el obispillo y la base de la cola, blancos. Vive en cortados y laderas rocosas, donde construye junto al nido una plataforma de piedrecitas que acarrea una a una. Su canto es potente y melodioso.', NULL, 'Cuerpo negro con obispillo blanco muy contrastado; «T» negra invertida en la cola blanca al volar; Montoncitos de piedrecitas junto a la grieta del nido', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Black_Wheatear%2C_Isla_Plana_3.jpg?width=1280', 'Andrew Thomas from Shrewsbury, UK (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Oenanthe', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia: De interés especial', 'El PORN cita la presencia de la especie en el parque sin detallar su categoría exacta de protección regional; pendiente de confirmar con el Catálogo Regional vigente. La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 11592, 5231236, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Chova piquirroja', 'Pyrrhocorax pyrrhocorax', 'fauna', 'Ave', 'Cortados rocosos, cantiles y montañas, alimentándose en pastizales cercanos', 'LC', 'Córvido negro y brillante con el pico rojo, largo y curvo, y las patas del mismo color encendido. Vuela en grupos acrobáticos junto a los cantiles, plegando las alas y dejándose caer por puro juego. Busca larvas hurgando en el suelo de los pastos con ese pico de sonda.', NULL, 'Pico rojo, largo y curvado hacia abajo; Reclamo agudo, un «chiaa» nasal muy característico; Plumas de la punta del ala muy separadas, como dedos', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pyrrhocorax_pyrrhocorax_-standing-8.jpg?width=1280', 'File:Alpenkrähe.jpg: "Malte Uhl (User:Zzzip)" derivative work: Snow… (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia (Ley 7/1995): De interés especial","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List) para la presencia en la ZEPA/ZEC ES0000173; IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Aves', NULL, NULL, 'Pyrrhocorax', 'LC (Preocupación menor)', 'LESRPE (RD 139/2011); Directiva Aves 2009/147/CE, Anexo I; Ley 42/2007, Anexo IV', 'Catálogo Regional de Especies Amenazadas de la Fauna Silvestre de Murcia (Ley 7/1995): De interés especial', NULL, 12065, 2482552, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Tórtola europea', 'Streptopelia turtur', 'fauna', 'Ave', 'Sotos, arboledas y matorral alto junto a cultivos y ramblas', 'VU', 'La más pequeña y grácil de nuestras palomas, con el dorso escamado en negro y canela y un parche a rayas blancas y negras en el cuello. Su arrullo ronco y adormecedor es uno de los sonidos del verano. Sus poblaciones han caído mucho en Europa por la pérdida de barbechos y setos.', NULL, 'Espalda escamada, como un mosaico canela y negro; Parche rayado blanco y negro a los lados del cuello; Arrullo ronco y vibrante, muy distinto al de la tórtola turca', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Streptopelia_turtur_Grlica0036.jpg?width=1280', 'Zrno at Serbian Wikipedia (Public domain) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE, Anexo II (especie cinegética)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE, Anexo II (especie cinegética)","ambito":"estatal","origen":"spainStatus del park.json"}', 1, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List) para la presencia en la ZEPA/ZEC ES0000173; IEPNB, Lista Patrón de las especies silvestres presentes en España (Resolución de 3 de diciembre de 2020), consultada 2026-07-25', 'Chordata', 'Aves', NULL, NULL, 'Streptopelia', 'VU (Vulnerable)', 'No incluida en el LESRPE; Directiva Aves 2009/147/CE, Anexo II (especie cinegética); Reglamento CITES, Anexo A', 'Ave de la ZEPA ES0000261 (Almenara, Moreras y Cabo Cope)', NULL, 12356, 2495708, 'ES0000173', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Abubilla', 'Upupa epops', 'fauna', 'Ave', 'Campos abiertos, dehesas, cultivos con arbolado y bordes de matorral', 'LC', 'Ave inconfundible de color canela con alas y cola a franjas blancas y negras, y una cresta eréctil que despliega en abanico al posarse. Sondea el suelo blando con el pico largo y curvo en busca de larvas e insectos. Su canto, un «up-up-up» sordo y repetido, se oye de lejos en primavera.', NULL, 'Vuelo ondulante y torpe, como una mariposa grande; Cresta que abre en abanico justo al aterrizar; Camina por el suelo clavando el pico largo y curvo', 'Todo el año en el sur peninsular; estival en el resto', 'https://commons.wikimedia.org/wiki/Special:FilePath/Wiedehopf_mit_Puppe_als_Futter.jpg?width=1280', 'Sven Damerow (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List) para la presencia en la ZEPA/ZEC ES0000173', 'Chordata', 'Aves', NULL, NULL, 'Upupa', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'Ave de la ZEPA ES0000261 (Almenara, Moreras y Cabo Cope)', NULL, 11211, 2498415, 'ES0000173', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Bisbita campestre', 'Anthus campestris', 'fauna', 'Ave', 'Llanos secos, pastizales ralos y claros pedregosos con poca vegetación', 'LC', 'Bisbita grande, esbelto y de tonos arena, con muy poco rayado en el pecho comparado con sus parientes. Camina por el suelo desnudo moviendo la cola arriba y abajo. Anida entre piedras y matas bajas, y su canto es una frase corta y monótona que emite en vuelo.', NULL, 'Pecho casi liso, sin el rayado denso de otros bisbitas; Camina en vez de saltar, meneando la cola; Ceja clara marcada y patas largas y pálidas', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/AnthusCampestris_cropped.jpg?width=1280', 'AnthusCampestris.jpg: Lip Kee derivative work: Bogbumper (talk) (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28.', 'Chordata', 'Aves', 'Passeriformes', 'Motacillidae', 'Anthus', 'LC (Preocupación menor) (evaluación UICN 2018)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero) · Anexo IV (Ley 42/2007, de 13 de diciembre)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 10944, 2490274, 'ES0000173', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Bisbita alpino', 'Anthus spinoletta', 'fauna', 'Ave', 'Pastos de montaña en verano; orillas, ramblas y encharcados en invierno', 'LC', 'Bisbita robusto de patas oscuras que cría en la alta montaña y en invierno baja a orillas de agua y campos húmedos. En plumaje nupcial adquiere un pecho rosado y sin rayas; en invierno queda pardo grisáceo con el pecho listado.', NULL, 'Patas oscuras, no rosadas como en otros bisbitas; Ceja blanca clara sobre el ojo; En invierno, casi siempre junto a agua o suelo húmedo', 'Otoño e invierno fuera de la alta montaña', 'https://commons.wikimedia.org/wiki/Special:FilePath/Anthus_spinoletta.jpg?width=1280', 'Original uploader was Marboline at pl.wikipedia (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28.', 'Chordata', 'Aves', 'Passeriformes', 'Motacillidae', 'Anthus', 'LC (Preocupación menor) (evaluación UICN 2018)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 12231, 2490255, 'ES0000173', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Busardo ratonero', 'Buteo buteo', 'fauna', 'Ave rapaz', 'Mosaicos de bosque y campo abierto, con arbolado para nidificar', 'LC', 'La rapaz mediana más frecuente y variable de plumaje: los hay casi blancos y casi negros. Pasa mucho tiempo posado en postes y en el suelo, y planea en círculos con las alas ligeramente levantadas. Su reclamo es un maullido lastimero muy reconocible.', NULL, 'Planea en círculos con las alas en «V» poco marcada; Maullido agudo y quejumbroso al volar; Muy variable: desde ejemplares claros a muy oscuros', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Buizerd-rh_20091021_002_(cropped).jpg?width=1280', 'RonaldHuijssen (CC BY-SA 3.0 nl) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28.', 'Chordata', 'Aves', 'Accipitriformes', 'Accipitridae', 'Buteo', 'LC (Preocupación menor) (evaluación UICN 2021)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 10922, 2480537, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Chotacabras europeo', 'Caprimulgus europaeus', 'fauna', 'Ave', 'Claros de bosque, brezales y matorral con suelo desnudo', 'LC', 'Ave nocturna de plumaje jaspeado que descansa de día tumbada a lo largo de una rama o en el suelo, confundida con la corteza. Caza polillas al vuelo con la boca enorme. Su canto es un ronroneo continuo y mecánico que puede durar minutos sin pausa.', NULL, 'Canto como un motor lejano, continuo y vibrante; Vuela al anochecer con giros silenciosos y bruscos; El macho muestra manchas blancas en alas y cola', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Nachtzwaluw_-_European_nightjar_-_Caprimulgus_europaeus_2.jpg?width=1280', 'Bouke ten Cate (CC BY 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28.', 'Chordata', 'Aves', 'Caprimulgiformes', 'Caprimulgidae', 'Caprimulgus', 'LC (Preocupación menor) (evaluación UICN 2016)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero) · Anexo IV (Ley 42/2007, de 13 de diciembre)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 11229, 8109681, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Agateador común', 'Certhia brachydactyla', 'fauna', 'Ave', 'Bosques y arboledas con troncos gruesos y corteza resquebrajada', 'LC', 'Pájaro diminuto y críptico que sube por los troncos en espiral, apoyándose en la cola rígida, y baja volando a la base del árbol siguiente para empezar de nuevo. Extrae insectos de las grietas de la corteza con un pico fino y curvado.', NULL, 'Trepa siempre hacia arriba, nunca cabeza abajo; Dorso jaspeado como corteza y vientre blanco; Pico fino y curvo, como una aguja doblada', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Short-toed_Treecreeper_(Certhia_brachydactyla)_(cropped_version).jpg?width=1280', 'Short-toed_Treecreeper_(Certhia_brachydactyla).jpg: א (Aleph) deriv… (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28.', 'Chordata', 'Aves', 'Passeriformes', 'Certhiidae', 'Certhia', 'LC (Preocupación menor) (evaluación UICN 2016)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 10733, 7806848, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Aguilucho cenizo', 'Circus pygargus', 'fauna', 'Ave rapaz', 'Cerealistas, herbazales y matorral bajo en zonas llanas', 'LC', 'Aguilucho grácil y de alas largas y estrechas que patrulla a poca altura, basculando con el viento y con las alas en «V». El macho es gris ceniza con las puntas negras; la hembra, parda y listada, con un obispillo blanco. Cría en el suelo, entre la vegetación.', NULL, 'Vuelo bajo y balanceante, con las alas en «V»; Macho gris ceniza con una barra negra en el ala; Alas muy largas y estrechas en proporción al cuerpo', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Flickr_-_don_macauley_-_Bird_015.jpg?width=1280', 'Donald Macauley (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28.', 'Chordata', 'Aves', 'Accipitriformes', 'Accipitridae', 'Circus', 'LC (Preocupación menor) (evaluación UICN 2021)', 'CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero) · Anexo IV (Ley 42/2007, de 13 de diciembre)', 'Vulnerable (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Mu…)', NULL, 12048, 2480495, 'ES0000173', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Codorniz común', 'Coturnix coturnix', 'fauna', 'Ave', 'Cereales, herbazales altos y pastizales densos', 'LC', 'La más pequeña de nuestras gallináceas y la única migradora. Es mucho más fácil de oír que de ver: su canto trisilábico —el clásico «pal-pa-lá»— se emite desde el interior del cereal. Solo levanta el vuelo cuando se la pisa casi encima, y lo hace en línea recta y rasante.', NULL, 'Canto trisilábico repetido desde dentro del herbazal; Vuela raso y en línea recta al levantarse; Del tamaño de un puño, mucho menor que una perdiz', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Quaglia.jpg?width=1280', 'Raniero Massoli Novelli (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 1, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28.', 'Chordata', 'Aves', 'Galliformes', 'Phasianidae', 'Coturnix', 'LC (Preocupación menor) (evaluación UICN 2018)', 'UICN España: DD (Datos insuficientes) (2004)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 11094, 2474156, 'ES0000173', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Esmerejón', 'Falco columbarius', 'fauna', 'Ave rapaz', 'Llanos abiertos, marismas y pastizales durante la invernada', 'LC', 'El halcón más pequeño de Europa, poco mayor que un mirlo, con vuelo rápido y bajo pegado al terreno para sorprender a pequeñas aves. El macho es gris azulado por encima; la hembra, parda. No se ciñe como el cernícalo: siempre está en movimiento.', NULL, 'Muy pequeño y compacto, con aleteo rápido; Vuela bajo y en línea recta, casi rozando el suelo; Sin bigotera marcada, a diferencia del peregrino', 'Otoño e invierno', 'https://commons.wikimedia.org/wiki/Special:FilePath/Falco_columbarius_Male.jpg?width=1280', 'Raj Boora from Edmonton, Canada (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28.', 'Chordata', 'Aves', 'Falconiformes', 'Falconidae', 'Falco', 'LC (Preocupación menor) (evaluación UICN 2021)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero) · Anexo IV (Ley 42/2007, de 13 de diciembre)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 11059, 9813242, 'ES0000173', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Alcotán', 'Falco subbuteo', 'fauna', 'Ave rapaz', 'Campo abierto con arbolado disperso, cerca de zonas húmedas', 'LC', 'Halcón esbelto con silueta de vencejo gigante: alas muy largas y afiladas y cola corta. Caza libélulas e incluso vencejos en pleno vuelo, con una agilidad extraordinaria. Los adultos tienen los «calzones» y la zona anal de un rojo ladrillo característico.', NULL, 'Silueta de hoz, como un vencejo enorme; Calzones y bajo vientre rojizos en el adulto; Bigotera negra ancha sobre garganta blanca', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hobby_-_Falco_subbuteo.jpg?width=1280', 'Andy Morffew from Itchen Abbas, Hampshire, UK (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28.', 'Chordata', 'Aves', 'Falconiformes', 'Falconidae', 'Falco', 'LC (Preocupación menor) (evaluación UICN 2021)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 12262, 2481035, 'ES0000173', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Pimientera', 'Fringilla coelebs', 'fauna', 'Ave', 'Bosques, arboledas, huertos y jardines con arbolado', 'LC', 'Uno de los pájaros más abundantes de Europa. El macho luce el pecho vinoso y la nuca gris azulada; la hembra es parda. Ambos comparten dos barras alares blancas muy visibles en vuelo. Su canto es una frase descendente que acaba en un floreo, repetida sin descanso en primavera.', NULL, 'Dos barras blancas bien marcadas en cada ala; Bordes blancos en la cola, visibles al volar; Canto en frase descendente que remata en un adorno', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fringilla_coelebs_(chaffinch)%2C_male.jpg?width=1280', 'Self: Commons user MichaelMaggs (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28.', 'Chordata', 'Aves', 'Passeriformes', 'Fringillidae', 'Fringilla', 'LC (Preocupación menor) (evaluación UICN 2019)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 11047, 2494422, 'ES0000173', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
