    SELECT 'Alondra totovía', 'Lullula arborea', 'fauna', 'Ave', 'Claros de bosque, dehesas y laderas con matorral y árboles dispersos', 'LC', 'Alondra pequeña de cola muy corta y cresta discreta, con una ceja blanca ancha que se une en la nuca. Canta en vuelo circular, sobre todo al amanecer y en noches claras, con una frase melancólica y descendente de una belleza reconocida.', NULL, 'Cola muy corta, silueta rechoncha en vuelo; Cejas blancas que se juntan por detrás de la cabeza; Marca blanca y negra en el borde delantero del ala', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lullula_arborea.jpg?width=1280', 'autor no indicado (Public domain) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28.', 'Chordata', 'Aves', 'Passeriformes', 'Alaudidae', 'Lullula', 'LC (Preocupación menor) (evaluación UICN 2019)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero) · Anexo IV (Ley 42/2007, de 13 de diciembre)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 10750, 2490604, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
