    SELECT 'Acentor alpino', 'Prunella collaris', 'fauna', 'Ave', 'Roquedos y pedreras de alta montaña; en invierno baja a cortados', 'LC', 'Pájaro robusto de montaña, pardo y discreto salvo por dos detalles: los flancos con listas castañas y una garganta blanca finamente moteada de negro. Camina entre las rocas buscando insectos y semillas, y en invierno desciende a cortados y construcciones.', NULL, 'Flancos con anchas listas castañas; Garganta blanca con motas negras, como un babero; Base del pico amarilla', 'Otoño e invierno en cotas bajas', 'https://commons.wikimedia.org/wiki/Special:FilePath/Alpine_accentor_saganta.jpg?width=1280', 'Paco Gómez from Castellón, Spain (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28.', 'Chordata', 'Aves', 'Passeriformes', 'Prunellidae', 'Prunella', 'LC (Preocupación menor) (evaluación UICN 2016)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 11054, 5231770, 'ES0000173', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Curruca rabilarga', 'Curruca undata', 'fauna', 'Ave', 'Matorral bajo y denso, jarales, brezales y tomillares', 'NE', 'Curruca pequeña, oscura y de cola muy larga que suele llevar levantada. El macho tiene el vientre vinoso y el ojo rojo rodeado de un anillo del mismo color. Es muy inquieta y rara vez se deja ver más de unos segundos antes de volver a hundirse en la mata.', NULL, 'Cola larga y erguida, casi vertical al posarse; Ojo y anillo ocular rojos; Vientre de color vinoso, con motitas blancas en la garganta', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fauvette_pitchou_Ichkeul_NP.jpg?width=1280', 'El Golli Mohamed (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 0, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28. Nombre aceptado en EIDOS; Sylvia undata es sinónimo.', 'Chordata', 'Aves', 'Passeriformes', 'Sylviidae', 'Curruca', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', 'Identificadores corregidos el 2026-08-09: tenía eidosTaxonId 80230, que es Sylvia undata undata (la subespecie), y la gbifSpeciesKey del sinónimo. La especie es Curruca undata (EIDOS 80931).', 80931, 2492949, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Mirlo capiblanco', 'Turdus torquatus', 'fauna', 'Ave', 'Montaña con matorral y pastos; en paso, sierras con enebros y bayas', 'LC', 'Mirlo de montaña que se distingue del común por una banda blanca en forma de media luna sobre el pecho y por las plumas del ala ribeteadas de claro, que dan un aspecto escamado. Es muy desconfiado y se aleja en cuanto detecta movimiento.', NULL, 'Media luna blanca en el pecho; Alas con aspecto escamado y plateado; Mucho más esquivo que el mirlo común', 'Paso migratorio e invernada en montaña', 'https://commons.wikimedia.org/wiki/Special:FilePath/2015-04-20_Turdus_torquatus_torquatus_Cairngorm_3.jpg?width=1280', 'MPF (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28.', 'Chordata', 'Aves', 'Passeriformes', 'Turdidae', 'Turdus', 'LC (Preocupación menor) (evaluación UICN 2019)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 12324, 7865305, 'ES0000173', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
