    SELECT 'Alcaudón real', 'Lanius meridionalis', 'fauna', 'Ave', 'Campo abierto con matorral disperso, cables y posaderos altos', 'VU', 'Alcaudón grande, gris por encima y con un antifaz negro que le cruza el ojo. Caza al acecho desde un posadero alto y tiene la costumbre de empalar sus presas —insectos, lagartijas, ratones— en espinas y alambres, formando pequeñas despensas.', NULL, 'Antifaz negro sobre fondo gris claro; Siempre en lo alto de un cable, poste o mata; Presas empaladas en espinos cerca de su territorio', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%BCdlicher-Raubw%C3%BCrger_2018-01-07_0003.jpg?width=1280', 'Andreas Trepte (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 1, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28.', 'Chordata', 'Aves', 'Passeriformes', 'Laniidae', 'Lanius', 'VU (Vulnerable) (evaluación UICN 2017)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011); UICN España: NT (Casi amenazado) (2004)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 16426, 7341500, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Curruca tomillera', 'Curruca conspicillata', 'fauna', 'Ave', 'Matorral bajo y abierto, tomillares y saladares con arbustos dispersos', 'LC', 'Curruca menuda de matorral raso, gris en la cabeza, parda en el dorso y con las plumas del ala ribeteadas de castaño encendido. El anillo blanco del ojo le da el aire de «gafas» que le da nombre. Es inquieta y suele delatarse por su reclamo antes de dejarse ver.', NULL, 'Anillo blanco alrededor del ojo bien marcado; Panel castaño vivo en el ala plegada; Vive en matorral muy bajo, no en arbolado', 'Todo el año en el sureste; parcialmente migradora', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fauvette_%C3%A0_lunettes_Aqueduc_de_Zaghouan.jpg?width=1280', 'El Golli Mohamed (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28. Nombre en BISE: Sylvia conspicillata (reclasificado en EIDOS).', 'Chordata', 'Aves', 'Passeriformes', 'Sylviidae', 'Curruca', 'LC (Preocupación menor)', 'Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 80923, 9868071, 'ES0000173', NULL, NULL
    UNION ALL
    SELECT 'Tarabilla europea', 'Saxicola rubicola', 'fauna', 'Ave', 'Matorral bajo, herbazales, ribazos y bordes de cultivo con posaderos', 'NE', 'Pájaro pequeño y regordete que se posa en lo alto de las matas, muy erguido y a la vista, para lanzarse al suelo a por insectos. El macho tiene la cabeza negra, un collar blanco a los lados y el pecho naranja. Su reclamo suena como dos piedras golpeadas, de donde le viene el nombre.', NULL, 'Siempre en lo alto de una mata, bien visible; Macho con capucha negra y medio collar blanco; Reclamo como el chasquido de dos cantos rodados', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Malestonechatseaham_Cropped.jpg?width=1280', 'derivative work: Myosotis Scorpioides (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28. Nombre en BISE: Saxicola torquatus (reclasificado en EIDOS).', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Saxicola', 'LC (Preocupación menor)', 'Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 16387, 4408759, 'ES0000173', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Murciélago mediano de herradura', 'Rhinolophus mehelyi', 'fauna', 'Murciélago', 'Cuevas cálidas del ámbito mediterráneo; caza en matorral y bosque abierto', 'VU', 'Murciélago de herradura mediterráneo, uno de los más escasos y amenazados de Europa. Se reconoce por un antifaz oscuro alrededor de los ojos y por el contraste neto entre el dorso pardo grisáceo y el vientre casi blanco. Depende por completo de un puñado de cuevas.', NULL, 'Antifaz oscuro marcado alrededor de los ojos; Contraste fuerte entre dorso gris pardo y vientre blanquecino; Hoja nasal ancha en la base que se estrecha de golpe', 'Todo el año (hiberna en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rhinolophus_mehelyi-cropped.jpg?width=1280', 'F. C. Robiller / naturlichter.de (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 1, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado', 'Chordata', 'Mammalia', 'Chiroptera', 'Rhinolophidae', 'Rhinolophus', 'VU (Vulnerable) (evaluación UICN 2016)', 'CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero) · Anexo II (Ley 42/2007, de 13 de diciembre) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'Vulnerable (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Mu…)', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 11702, 2432667, NULL, NULL, NULL
    UNION ALL
    SELECT 'Murciélago de cueva', 'Miniopterus schreibersii', 'fauna', 'Murciélago', 'Cuevas y minas; caza en vuelo alto sobre bosque, campo y láminas de agua', 'VU', 'Murciélago de alas largas y estrechas y vuelo rápido y alto, casi como el de un vencejo. Tiene la frente muy abombada y el pelo corto y erizado en la cabeza. Recorre decenas de kilómetros entre las cuevas de cría, de tránsito y de invernada.', NULL, 'Frente muy abombada y pelo corto y de punta; Alas largas y estrechas; vuelo veloz y alto; Forma colonias enormes y muy apretadas en cueva', 'Todo el año, con desplazamientos estacionales entre cuevas', 'https://commons.wikimedia.org/wiki/Special:FilePath/Miniopterus_schreibersii_dasythrix.jpg?width=1280', 'Andrew Smith (Public domain) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 1, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado', 'Chordata', 'Mammalia', 'Chiroptera', 'Miniopteridae', 'Miniopterus', 'VU (Vulnerable) (evaluación UICN 2023)', 'CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero) · Anexo II (Ley 42/2007, de 13 de diciembre) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', 'Foto localizada por búsqueda en Commons (no por el elemento de Wikidata del taxón): conviene confirmar que corresponde a esta especie. La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 12169, NULL, NULL, NULL, NULL
    UNION ALL
    SELECT 'Murciélago ratonero mediano', 'Myotis blythii', 'fauna', 'Murciélago', 'Cuevas y desvanes; caza saltamontes en pastizales y herbazales', 'LC', 'Casi idéntico al ratonero grande, con el que a menudo comparte colonia, pero algo menor y con el hocico más estrecho y una mancha clara en la frente. Está especializado en cazar saltamontes en pastizales altos, lo que reparte el alimento entre ambas especies.', NULL, 'Muy parecido al ratonero grande, pero algo menor; Mancha clara difusa entre los ojos; Hocico más fino y estrecho', 'Todo el año (hiberna en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Myotis-blythii-cropped.jpg?width=1280', 'C. Robiller / www.naturlichter.de (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado', 'Chordata', 'Mammalia', 'Chiroptera', 'Vespertilionidae', 'Myotis', 'LC (Preocupación menor) (evaluación UICN 2016)', 'CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero) · Anexo II (Ley 42/2007, de 13 de diciembre) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Mu…)', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 10866, NULL, NULL, NULL, NULL
    UNION ALL
    SELECT 'Murciélago patudo', 'Myotis capaccinii', 'fauna', 'Murciélago', 'Cuevas próximas a ríos y balsas; caza rozando la lámina de agua', 'VU', 'Murciélago ligado al agua: caza volando a pocos centímetros de la superficie de ríos y balsas y captura insectos —e incluso pececillos— con sus pies desproporcionadamente grandes y peludos. Esa dependencia del agua limpia lo hace muy vulnerable.', NULL, 'Pies muy grandes y peludos en proporción al cuerpo; Vuela rozando la lámina de agua; Membrana del ala insertada en el tobillo, no en el dedo', 'Todo el año (hiberna en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Myotis_capaccinii_0105b_cropped.jpg?width=1280', 'This image was improved or created by the Wikigraphists of the Grap… (FAL) · Wikimedia Commons', NULL, NULL, 5, '{"categoria":"CEEA: En peligro de extinción (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"CEEA: En peligro de extinción (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 1, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado', 'Chordata', 'Mammalia', 'Chiroptera', 'Vespertilionidae', 'Myotis', 'VU (Vulnerable) (evaluación UICN 2016)', 'Anexo II (Ley 42/2007, de 13 de diciembre, del Patrimonio Natural y de la Biodiversidad. BOE 299, de 14 de diciembre de 2007); Anexo V (Ley 42/2007, de 13 de diciembre, del Patrimonio Natural y de la Biodiversidad. BOE 299, de 14 de diciembre de 2007); CEEA: En peligro de extinción (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011); UICN España: EN (En peligro) (2007)', 'Vulnerable (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Mu…)', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 10958, NULL, NULL, NULL, NULL
    UNION ALL
    SELECT 'Murciélago de Geoffroy o de oreja partida', 'Myotis emarginatus', 'fauna', 'Murciélago', 'Cuevas y desvanes; caza arañas e insectos en el follaje de bosques y sotos', 'LC', 'Murciélago de pelaje lanoso y rojizo, con una escotadura muy marcada en el borde de la oreja que le da nombre. Recoge sus presas directamente del follaje y de las paredes, cerniéndose frente a ellas, en vez de capturarlas en pleno vuelo.', NULL, 'Muesca clara en el borde externo de la oreja; Pelaje lanoso y de tono rojizo; Se ciñe frente a hojas y muros para capturar arañas', 'Todo el año (hiberna en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Myotis_emarginatus.jpg?width=1280', 'Rémi Bigonneau (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado', 'Chordata', 'Mammalia', 'Chiroptera', 'Vespertilionidae', 'Myotis', 'LC (Preocupación menor) (evaluación UICN 2016)', 'CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero) · Anexo II (Ley 42/2007, de 13 de diciembre) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 11206, NULL, NULL, NULL, NULL
    UNION ALL
    SELECT 'Murciélago ratonero grande', 'Myotis myotis', 'fauna', 'Murciélago', 'Cuevas y desvanes; caza escarabajos en pastos, claros y bosque sin sotobosque', 'LC', 'Uno de los murciélagos más grandes de Europa, con orejas largas y anchas y hocico de aspecto perruno. Caza cerca del suelo, capturando escarabajos que localiza por el ruido que hacen al andar, no solo con el sonar. Cría en colonias numerosas en cuevas y bajo cubiertas.', NULL, 'Talla grande y orejas largas y anchas; Hocico ancho, de aspecto casi perruno; Caza a ras de suelo, en zonas despejadas', 'Todo el año (hiberna en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Myotis.jpg?width=1280', 'Urheber: Manuel Werner, Germany, Wikipedia-Kontakt: http://de.wikip… (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado', 'Chordata', 'Mammalia', 'Chiroptera', 'Vespertilionidae', 'Myotis', 'LC (Preocupación menor) (evaluación UICN 2016)', 'CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero) · Anexo II (Ley 42/2007, de 13 de diciembre) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Mu…)', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 11803, NULL, NULL, NULL, NULL
    UNION ALL
    SELECT 'Murciélago de herradura mediterráneo', 'Rhinolophus euryale', 'fauna', 'Murciélago', 'Cuevas cálidas; caza en bosque mediterráneo y mosaicos arbolados', 'NT', 'Murciélago de herradura de tamaño medio, de costumbres muy cavernícolas, que forma colonias de cría densas junto a otras especies. Vuela muy pegado a la vegetación, capturando polillas entre las ramas. Sus colonias son muy vulnerables a la visita de cuevas en primavera.', NULL, 'Talla intermedia entre el grande y el pequeño de herradura; Apéndice superior de la nariz apuntado y algo curvado; Forma colonias apretadas en cueva, con otras especies', 'Todo el año (hiberna en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rhinolophus_euryale-cropped.jpg?width=1280', 'Carlosblh (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado', 'Chordata', 'Mammalia', 'Chiroptera', 'Rhinolophidae', 'Rhinolophus', 'NT (Casi amenazado) (evaluación UICN 2016)', 'CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero) · Anexo II (Ley 42/2007, de 13 de diciembre) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Mu…)', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 11230, NULL, NULL, NULL, NULL
    UNION ALL
    SELECT 'Murciélago grande de herradura', 'Rhinolophus ferrumequinum', 'fauna', 'Murciélago', 'Cuevas, minas y desvanes para refugiarse; caza en mosaicos de bosque y pasto', 'LC', 'El mayor de los murciélagos de herradura ibéricos. Debe el nombre a la hoja nasal en forma de herradura con la que emite el sonar por la nariz, no por la boca. Al reposar se envuelve por completo en las alas, como en una capa, y cuelga libre del techo.', NULL, 'Al dormir se envuelve entero en las alas; Hoja nasal en forma de herradura alrededor de las fosas; Cuelga separado del techo, no metido en una grieta', 'Todo el año (hiberna en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Grand_Rhinolophe_2.jpg?width=1280', 'Marie Jullion (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado', 'Chordata', 'Mammalia', 'Chiroptera', 'Rhinolophidae', 'Rhinolophus', 'LC (Preocupación menor) (evaluación UICN 2016)', 'CEEA: Vulnerable (Real Decreto 139/2011, de 4 de febrero) · Anexo II (Ley 42/2007, de 13 de diciembre) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Mu…)', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 11264, NULL, NULL, NULL, NULL
    UNION ALL
    SELECT 'Murciélago pequeño de herradura', 'Rhinolophus hipposideros', 'fauna', 'Murciélago', 'Cuevas, minas y edificios; caza en bosque, sotos y setos', 'LC', 'El más pequeño de los murciélagos de herradura europeos: colgado y envuelto en sus alas no llega al tamaño de una ciruela. Vuela bajo y muy cerca de la vegetación, con revoloteo de mariposa. Es muy sensible a las molestias en sus refugios de cría e invernada.', NULL, 'Tamaño minúsculo, como una ciruela colgando; Vuelo bajo y revoloteante junto a setos y muros; Se envuelve en las alas al reposar, como sus parientes', 'Todo el año (hiberna en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kleine_Hufeisennase.jpg?width=1280', 'F. C. Robiller / naturlichter.de (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Mu…)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado', 'Chordata', 'Mammalia', 'Chiroptera', 'Rhinolophidae', 'Rhinolophus', 'LC (Preocupación menor) (evaluación UICN 2016)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero) · Anexo II (Ley 42/2007, de 13 de diciembre) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Mu…)', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 11451, NULL, NULL, NULL, NULL
    UNION ALL
    SELECT 'Galápago leproso', 'Mauremys leprosa', 'fauna', 'Reptil', 'Ríos, charcas, balsas y tramos remansados con vegetación y soleaderos', 'NE', 'Galápago de agua con el caparazón aplanado y de color verde oliva a pardo, a menudo cubierto de algas. Los ejemplares jóvenes muestran manchas anaranjadas en el cuello y en los lados de la cabeza que se van apagando con la edad. Toma el sol sobre piedras y troncos y se lanza al agua al menor ruido.', NULL, 'Manchas anaranjadas en el cuello, más vivas de joven; Caparazón bajo y aplanado, a menudo con algas; Se tira al agua en cuanto detecta movimiento en la orilla', 'Primavera a otoño (inactivo en invierno)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mauremys_leprosa_03_by-dpc.jpg?width=1280', 'David Perez (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado', 'Chordata', 'Reptilia', 'Testudines', 'Geoemydidae', 'Mauremys', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero) · Anexo II (Ley 42/2007, de 13 de diciembre) · Anexo V (Ley 42/2007, de 13 de diciembre)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', 'La cita de presencia en este espacio procede del volcado inicial del catálogo, que reutilizó fichas de otro parque, y no de una fuente propia: pendiente de referenciar contra el PORN y el plan de gestión de este espacio.', 11585, NULL, NULL, NULL, NULL
    UNION ALL
    SELECT 'Calandria común', 'Melanocorypha calandra', 'fauna', 'Ave esteparia', 'Llanos cerealistas, pastizales y estepas de suelo profundo', 'LC', 'La mayor de las alondras ibéricas, robusta y de pico grueso, con una mancha negra muy marcada a cada lado del cuello. Canta en vuelo, describiendo círculos altos con un torrente de notas en el que imita a otras aves. En invierno forma bandos numerosos en los llanos.', NULL, 'Babero negro a cada lado del cuello; Borde trasero del ala blanco y visible en vuelo; Pico grueso y pálido, de granívora', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Melanocorypha_calandra.jpg?width=1280', 'Bereşe.jpg: Dûrzan cîrano derivative work: Osado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List) para la presencia en la ZEPA/ZEC ES0000173', 'Chordata', 'Aves', NULL, NULL, 'Melanocorypha', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'Ave de la ZEPA ES0000261 (Almenara, Moreras y Cabo Cope)', NULL, 10937, NULL, 'ES0000173', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Treparriscos', 'Tichodroma muraria', 'fauna', 'Ave', 'Paredes rocosas, cantiles y barrancos; en invierno baja a roquedos y edificios', 'LC', 'Pájaro de alta montaña que trepa por paredes verticales agitando las alas como una mariposa gigante, mostrando unos vistosos paneles rojos. Extrae insectos de las grietas con un pico largo y fino. En invierno desciende y puede aparecer en cortados bajos, castillos y presas.', NULL, 'Manchas rojo carmín en las alas al abrirlas; Trepa por la roca a saltos, aleteando sin parar; Pico largo, fino y algo curvado', 'Otoño e invierno fuera de la alta montaña', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tichodroma_muraria02_cropped.jpg?width=1280', 'derivative work: Hämbörger (talk) Tichodroma_muraria02.jpg: User:Kulac (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List) para la presencia en la ZEPA/ZEC ES0000173', 'Chordata', 'Aves', NULL, NULL, 'Tichodroma', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000)', 'Ave de la ZEPA ES0000261 (Almenara, Moreras y Cabo Cope)', NULL, 11796, NULL, 'ES0000173', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Tarabilla norteña', 'Saxicola rubetra', 'fauna', 'Ave', 'Herbazales, prados altos y cultivos con tallos donde posarse', 'LC', 'Tarabilla migradora que solo se ve en los pasos. Se distingue de la europea por una ceja blanca ancha y muy marcada y por las bases blancas de la cola. Como su parienta, se posa en lo alto de tallos y matas y baja al suelo a cazar insectos.', NULL, 'Ceja blanca ancha y bien marcada; Base de la cola blanca a ambos lados; Pecho anaranjado que va difuminándose hacia el vientre', 'Paso migratorio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Saxicola_rubetra_poklaskwa_AM.jpg?width=1280', 'Artur Mikołajewski (CC BY 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28.', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Saxicola', 'LC (Preocupación menor) (evaluación UICN 2016)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 12112, NULL, 'ES0000173', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000173","name":"Sierra Espuña","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000173 (Sierra Espuña), sección 3.2"}'
    UNION ALL
    SELECT 'Curruca carrasqueña', 'Curruca cantillans', 'fauna', 'Ave', 'Matorral alto, jarales, encinares aclarados y bordes de bosque', 'LC', 'Curruca de tamaño medio, con el macho de dorso gris, garganta y pecho color teja y un bigote blanco muy nítido que separa ambos. El anillo ocular es rojo. Canta desde el interior del matorral y hace vuelos cortos de exhibición sobre las matas.', NULL, 'Bigote blanco que bordea la garganta rojiza; Anillo ocular rojo anaranjado; Prefiere matorral alto, no el raso', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/%CE%9A%CE%BF%CE%BA%CE%BA%CE%B9%CE%BD%CE%BF%CF%84%CF%83%CE%B9%CF%81%CE%BF%CE%B2%CE%AC%CE%BA%CE%BF%CF%82.jpg?width=1280', 'Antonios Tsaknakis (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'EIDOS (IEPNB, MITECO) para taxonomía y estado; EEA/BISE (Site_Species_List, https://discodata.eea.europa.eu) para la presencia en la ZEPA/LIC ES0000173, consultado 2026-07-28. Nombre en BISE: Sylvia cantillans (reclasificado en EIDOS).', 'Chordata', 'Aves', 'Passeriformes', 'Sylviidae', 'Curruca', 'LC (Preocupación menor) (evaluación UICN 2019)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Decreto 50/2003 de protección de especies silvestres de la Región de Murcia (EIDOS, consultado 2026-07-28)', NULL, 80920, NULL, 'ES0000173', NULL, NULL
